insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 1, 'AKATA''s 2029 row is a net cash flow of minus 121123680.00 USD and its discounted cash flow is also minus 121123680.00. Why was the row not discounted?', '["Capex is never discounted, because it is spent at sanction and the factor applies only to the revenue that follows it.", "Negative flows are carried at face value so that the cost of the project is not understated by the discount.", "The exponent is the number of years between the row and the valuation year, and 2029 is the valuation year, so the exponent is zero.", "The engine starts discounting from the first production year, 2030, and treats the sanction year as time zero for prices only."]'::jsonb, 2, 'The 2030 row, one year out, is divided by 1.1 once, 31746007.20 to 28860006.55; the base year row is divided by nothing.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 2, 'The 2030 row of AKATA keeps 28860006.55 of its 31746007.20, while the 2035 row keeps only 17161022.43 of 30401798.05. What makes the 2035 row lose the larger share?', '["It is six divisions by 1.1 from 2029 rather than one.", "The 2035 flow is smaller, and the factor takes a larger share of a smaller row.", "The oil price escalator of 2 percent has lifted the 2035 price to 92.345318, so more nominal value is removed.", "The rate rises with each year of the horizon to price the growing risk of the tail."]'::jsonb, 0, 'Each row loses a larger share than the one before it because it is one more division further from 2029; the 2035 row is a little over half of itself.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 3, 'AKATA''s two capex years sum to 255000000.00 USD and their present value at the applied rate is 250909090.91. Why is the gap so small?', '["The capex escalator is set to zero, and a row that does not escalate is exempt from the discount factor as well.", "Capex is discounted at the applied real rate of 6.796117 percent while revenue is discounted at the nominal 10.000000, so it is treated more gently.", "The engine nets each year''s depreciation of 25500000.00 against the capex before discounting, which leaves little to discount.", "The 2029 spend of 210000000.00 sits in the valuation year and is not discounted; only the 45000000.00 of 2030 shrinks."]'::jsonb, 3, 'Spend arrives early and is barely discounted; revenue arrives late and is discounted hard, which is why 141637829.18 undiscounted becomes an NPV of 72534830.66.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 4, 'jv_analytic_decision_kpis has a 2030 flow of minus 12500000.00 and a 2031 flow of 37500000.00, base year 2030, 10 percent, nominal, end-year. What is its NPV?', '["25000000.00, the plain sum of the rows, since two years is too short to discount.", "21590909.09, the first row whole plus the second divided by 1.1 once, 34090909.09.", "20586124.09, both rows divided by the square root of 1.1 because each sits half a year from the base date.", "23750000.00, because the 2030 flow is a year older than the 2031 flow and is carried forward by 1.1 to meet it."]'::jsonb, 1, 'The undiscounted total is 25000000.00; the discount touches the 2031 row alone, 37500000.00 to 34090909.09.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 5, 'What is discount_rate_pct to the engine?', '["A result the ledger reveals, the way the IRR of 29.2361 percent is revealed, once the rows are known.", "An input: the owner''s statement of what a year''s delay costs, or what the same capital could earn elsewhere, applied as a nominal rate.", "The inflation rate of 3 percent plus the price escalators, which is how a nominal rate is assembled from its parts.", "The rate at which the profile point equals the headline, a property the profile reveals once the rows are known, so that on AKATA the 10 percent point of 55805775.02 is the NPV."]'::jsonb, 1, 'AKATA carries 10, and nothing in its production, prices or fiscal terms produces that number.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 6, 'AKATA''s profile row labelled 10 percent reads 55805775.02, and AKATA''s discount rate is 10. Why is the headline NPV 72534830.66 instead?', '["The headline is evaluated under mid-year discounting and the profile under end-year, and the half-year shift accounts for the difference.", "The headline includes the undiscounted 2029 row of minus 121123680.00, which the profile leaves out because it is the valuation year.", "The profile is evaluated on the nominal flows and the headline on the real ones, so the profile carries three percent of inflation the headline has already removed.", "The profile is evaluated on the real flows, where the configured 10 percent nominal is 6.796117 percent real, and the headline sits at that rate."]'::jsonb, 3, 'A profile point labelled with your discount rate is your NPV only when the basis is nominal.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 7, 'From 0 to 5 percent AKATA''s profile falls from 117362408.71 to 83023565.60; from 15 to 20 it falls from 33900281.71 to 16026160.80. Why do the removals shrink as the rate rises?', '["The late years that a high rate punishes have already been reduced to little by the time the rate is high.", "The profile is sampled at uneven steps, 0, 5, 8, 10, 12, 15 and 20, and the later steps are simply closer together.", "The escalators of 2 and 3 percent offset more of the discount as the rate rises.", "The rate is applied to the real flows, which are smaller than the nominal ones, so each step has less to remove."]'::jsonb, 0, 'AKATA is still positive at 20 percent, 16026160.80, which is why its IRR sits beyond the table at 29.2361 percent.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 8, 'With inflation and every escalator set to zero, AKATA''s NPV is 65055328.97 on either basis. What does that say about the configured 72534830.66?', '["The 3 percent inflation lifts the answer by raising the revenue rows, and removing it exposes the flat prices underneath.", "The real basis adds value by deflating the capex of 255000000.00 in 2029 money, and the zero run loses that.", "The price and cost escalators lift the configured answer, not the inflation rate, which the discount rate refuses to carry on its own.", "The difference is the Fisher conversion of 10.000000 to 6.796117 percent, which the zero run no longer performs."]'::jsonb, 2, 'Set only inflation to zero and NPV stays 72534830.66; it is the escalators, not the deflator, that move the rows.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 9, 'Under mid_year_discounting the 2030 row goes from minus 12500000.00 to minus 11918282.37, the 2031 row to 32504406.45, and the NPV is 20586124.09 against the end-year 21590909.09. What is the relation between the two NPVs?', '["Mid-year shifts only the 2031 row by half a year, so the 2030 row stays at minus 12500000.00 and the NPV falls by the change in one row.", "The mid-year NPV is the end-year NPV divided by 1.1 once more, a full extra year on every row, which is why it is lower.", "The difference is the fiscal cascade: royalty of 20000000.00 is charged mid-year and tax of 32500000.00 at year end, so the timing of the two moves the sum.", "The mid-year NPV is the end-year NPV divided by the square root of 1.1, because every exponent moved by half."]'::jsonb, 3, 'Every row, the base year row included, was scaled by one factor, so the sum was scaled by the same factor.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 10, 'AKATA reads 72534830.66 end-year and 69159247.46 mid-year on the nominal basis, but 72534830.66 and 70188970.32 on the real basis. Why do the two conventions differ less on the real basis?', '["The real flows are smaller, 117362408.71 against 141637829.18 in total, so there is less for the half-year shift to remove.", "Half a year at 6.796117 percent is a smaller division than half a year at 10 percent.", "The real basis shifts only the years after 2029, leaving the capex row whole.", "The real basis deflates the half-year shift by 3 percent of inflation on top of the rate, and the two shifts partly cancel."]'::jsonb, 1, 'The nominal gap runs 72534830.66 to 69159247.46; the real gap only 72534830.66 to 70188970.32.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 11, 'Which readings of AKATA does mid-year discounting leave unchanged?', '["The IRR of 29.2361 percent, the discounted payback of 3.961607 years and the DPI, because a uniform scaling of every discounted row cannot move a zero crossing or a ratio.", "The NPV, because the half-year shift applies to the capex rows and to the revenue rows alike, and a change that scales the negative rows and the positive rows by the same factor cancels in the sum.", "The undiscounted total of 141637829.18, which mid-year raises by half a year of growth at the applied rate.", "The applied rate, which becomes the square root of 1.1 under mid-year on both bases."]'::jsonb, 0, 'The published mid-year case reports a DPI of 0.431818 and a discounted take of 82.2761 percent, identical to its end-year twin.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 12, 'A reader hand-checks AKATA''s mid-year NPV by shifting the 2030 to 2035 rows by half a year and leaving the 2029 row whole at minus 121123680.00. What happens?', '["The check reconciles, because the base year row carries an exponent of zero under either convention and cannot move.", "The check lands on 70188970.32, because leaving the capex row whole is what the real basis does under mid-year.", "The check will not reconcile: the engine discounts the valuation year row too, to minus 115486897.55.", "The check produces a smaller gap than 72534830.66 to 69159247.46, because the capex left at full size pulls the sum down."]'::jsonb, 2, 'Discounting the 2029 capex by half a year makes it cheaper in present value and partly offsets the shrinking of the revenue rows, so the true gap is smaller than the reader computes.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 13, 'One project is run end-year and reports 72534830.66; another is run mid-year and reports 69159247.46. Can they be ranked on those NPVs?', '["No. Between the two figures there is no information about either field, only a convention, and both must be run under the same one first.", "Yes, because mid-year is the more accurate convention and its lower figure is the conservative one to rank on.", "Yes, because the IRR of 29.2361 percent and the discounted payback of 3.961607 years are the same under both conventions, which shows that the NPVs are comparable too.", "Yes, provided both are on the nominal basis, since basis is the only setting that changes NPV."]'::jsonb, 0, 'The IRR and the discounted payback of 3.961607 years are unmoved by the convention; the NPV is not, so it cannot cross a convention boundary.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 14, 'What third timing choice does discounting_convention offer beside end_year and mid_year?', '["A start-of-year convention for capex-heavy fields, so that the 2029 spend of 210000000.00 is left undiscounted while revenue is shifted.", "Quarterly timing, applied when a year''s rows carry more than one entry per year.", "A split convention with capex at end-year and revenue at mid-year in the same year.", "None."]'::jsonb, 3, 'Every flow in a row is treated as arriving at one instant, so a January capex and a December capex in 2029 are worth the same.'),
  ('cashflow', 'intermediate', 'module', 'm01-why-time-matters', 15, 'Which of AKATA''s two conventions, end-year or mid-year, is the true one?', '["Mid-year, because the published mid_year_discounting case is the golden the engine was validated against.", "The engine cannot say: the rows are years, nothing records when within a year the cash moved, and choosing mid-year is a claim about the field that the engine will not check.", "End-year, because it gives the higher NPV of 72534830.66 and the engine reports the higher of the two readings.", "The engine tests both and keeps the one whose discounted payback matches the undiscounted 3.461632 years."]'::jsonb, 1, 'Where none is given it discounts end-year, and a default is still a choice the reader has to be told.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 1, 'AKATA is configured with inflation of 3 percent, an oil escalator of 2, a gas escalator of 2, an opex escalator of 3 and a capex escalator of 0. Which of those five rates write the ledger rows?', '["All five, with inflation raising the revenue rows on top of the price escalators.", "The four escalators. Inflation touches no row; it deflates the real_net_cash_flow column and derives the applied real rate.", "Inflation and the opex escalator, which the engine adds together because both are 3 percent and both act on costs.", "Only inflation, since the escalators are display settings that restate prices the inflation rate has already grown."]'::jsonb, 1, 'Oil goes from 82.000000 to 83.640000 in 2030 by the escalator alone, and the nominal total of 141637829.18 does not move when inflation is swept from 0 to 8 percent.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 2, 'AKATA''s 2033 net cash flow is 44874457.77 nominal and 39870374.51 real. What separates the two figures?', '["Three years of deflation, because the first row after the base year is not deflated either.", "The opex escalator of 3 percent compounding over the horizon and taken back out of the row.", "One year of the gap between the nominal 10 percent and the real 6.796117 percent, applied to the row.", "Four years of deflation at 3 percent, counted from the 2029 base year."]'::jsonb, 3, 'The 2029 row is the base year and is not deflated, minus 121123680.00 in both columns; 2030 is divided by one year of 3 percent, 2033 by four.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 3, 'Sweeping AKATA''s inflation from 0 to 8 percent with the escalators as configured, the nominal total net cash flow stays 141637829.18 while the real total falls to 83912631.29. What does the sweep prove?', '["With every escalator set, inflation touches no row; only the deflator grew.", "Above 3 percent the inflation rate overrides the escalators, and the real column records the rows it would have written.", "The nominal total is fixed because the engine reports it before inflation is applied, and the real total is the ledger after.", "The real total falls because the engine reduces the opex escalator by the inflation rate to keep costs in real terms."]'::jsonb, 0, 'Set inflation and every escalator to zero together and NPV becomes 65055328.97; set only inflation to zero and NPV stays 72534830.66.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 4, 'In escalator_defaults_to_inflation an oil price of 100.000000 becomes 105.000000 at 5 percent inflation with no oil escalator given, and opex of 10000000.00 becomes 10500000.00. What is the rule?', '["Inflation always adds to the escalators, so AKATA''s oil price grows at 2 plus 3 percent a year.", "The fallback applies to every cost line, so an unset capex escalator also grows capex at the inflation rate.", "When an escalator is unset the engine falls back to the inflation rate for oil and for opex, and to zero for capex; setting the escalator cuts the link.", "An unset escalator takes the value of the opex escalator, which in this case happens to equal the inflation rate."]'::jsonb, 2, 'AKATA''s escalators are all set explicitly, so its 3 percent inflation only deflates; the default decides the rows only where a key is left empty.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 5, 'With a nominal rate of 10 percent and inflation of 8, the engine reports an applied real rate of 1.851852 percent. What is the relation, and what would a subtraction have done?', '["The subtraction is the exact relation, and 1.851852 is the engine''s display rounding of the difference of the two rates.", "The real rate is the nominal less inflation less the opex escalator of 3, since costs inflate at their own rate.", "One plus the nominal over one plus the inflation, less one; a subtraction would have put the real rate higher.", "A subtraction would have put the real rate lower, because compounding at 8 percent removes more than the plain difference."]'::jsonb, 2, 'The gap grows with inflation and always in one direction: subtraction overstates the real rate, and an overstated rate understates every discounted row.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 6, 'Why does AKATA''s NPV read 72534830.66 at every inflation in the sweep, from 0 to 8 percent?', '["Deflating the flows and deflating the rate cancel exactly, because the real rate was built by dividing the inflation out of the nominal rate.", "The engine reports NPV on the nominal basis whatever basis is configured, so the deflator never reaches the headline.", "Inflation raises the revenue rows by exactly the amount the deflator later removes from them.", "The sweep resets the escalators to the inflation rate in each run, so the rows grow to compensate for the harsher deflator."]'::jsonb, 0, 'The 2033 flow of 44874457.77 deflates to 39870374.51 and discounts at 6.796117 percent to 30649858.46; at 10 percent on the nominal flow it is 30649858.46.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 7, 'A reader deflates AKATA''s flows correctly and then discounts them at a subtracted real rate. What comes out?', '["An NPV above 72534830.66, because a subtracted rate is lower than the Fisher rate and discounts less.", "The same 72534830.66, because the deflator and the rate cancel whatever real rate is used.", "The nominal 10 percent profile point of 55805775.02, since that is what the real flows give at a subtracted rate.", "An NPV below 72534830.66 with no row to blame, because an overstated rate understates every discounted row."]'::jsonb, 3, 'Check the applied real rate the engine prints, 6.796117 percent on AKATA; a hand calculation at any other rate will not reconcile.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 8, 'Is there a configuration key for a real discount rate?', '["Yes, real_discount_rate_pct, which AKATA sets to 6.796117 and the published real-basis cases to the same value.", "No. discount_rate_pct is nominal and the real rate is always derived from it and from inflation_rate_pct.", "The single discount_rate_pct key is read as real whenever present_value_basis is real and as nominal otherwise.", "There is no key because the escalators enter the conversion, so fields with different escalators carry different applied rates."]'::jsonb, 1, 'The applied real rate is 6.796117 percent on AKATA, multiyear_pia_real, multiyear_jv_real and pia_loss_relief whatever their prices do, because only the inflation rate enters it.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 9, 'Under mid-year discounting AKATA''s nominal basis gives 69159247.46 and its real basis 70188970.32, after agreeing at 72534830.66 under end-year. Why do the bases part?', '["The half-year shift divides by the square root of one plus the applied rate, and the applied rates differ, so the shift is smaller on the real basis.", "The real basis under mid-year deflates the 2029 row as well, which the end-year run had left whole.", "Mid-year shifts the real flows by half a year of inflation on top of half a year of the rate, and the two shifts compound.", "The gap is the profile''s rounding of 6.796117 to 6.8 percent, which only the mid-year run carries into the headline."]'::jsonb, 0, 'Basis does not move NPV under end-year; under mid-year it does, by about a million USD on AKATA.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 10, 'A field is presented with a total net cash flow of 117362408.71 from a real basis run, beside a competitor''s 141637829.18 from a nominal run of the same rows. What should a reader conclude?', '["The second field makes more money, since 141637829.18 exceeds 117362408.71 by the price escalation of 2 percent a year that the first field does not earn.", "The first field is the better investment, because its total is stated in 2029 purchasing power while the second is padded with inflated money of the day.", "The two are different fields whose NPVs would agree, since 72534830.66 is reported on both bases.", "It is one field. The undiscounted total is the one headline the basis changes, so it must never travel without its basis attached."]'::jsonb, 3, '141637829.18 is the cash that will pass through the account in the money of each year; 117362408.71 is what that would buy in 2029.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 11, 'On AKATA''s real basis run, which of the printed totals are still in money of the day?', '["None of them; a real basis run restates every total in 2029 purchasing power, and the net cash flow total is simply the last one printed.", "Revenue 857602518.80, capex 255000000.00, opex 183899092.34 and tax 148425219.46; only the net cash flow total of 117362408.71 is real.", "Only revenue 857602518.80, because prices carry the escalator and the cost totals are deflated with the net cash flow.", "The totals are all real and the rows are all nominal, which is the meaning of a real basis run."]'::jsonb, 1, 'The basis refuses to change the ledger; only real_net_cash_flow and the discounted column respond to it.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 12, 'In valuation_year_forward the 2030 row of minus 12500000.00 is reported as minus 13750000.00 in the discounted column. What happened to it?', '["It was flagged sunk, and the discounted column shows the flow with a year of interest charged against it.", "It was discounted one more year, because a later valuation year adds an exponent to every row.", "Valued in 2031, the 2030 flow is a year in the past and compounds forward by 1.1; NPV moves from 21590909.09 to 23750000.00.", "The fiscal cascade was rerun from 2031, and the larger negative is the 2030 capex with its depreciation of 5000000.00 removed."]'::jsonb, 2, 'The rows are unchanged, total net cash flow stays 25000000.00 and the fiscal columns, royalty 20000000.00 and tax 32500000.00, are identical; only the date of the statement moved.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 13, 'AKATA valued in 2030 with nothing sunk reports 77464382.26 against 72534830.66 valued in 2029. A reader reports that the project improved. What is wrong?', '["Nothing; the 2029 capex of 210000000.00 has already been paid, and a field valued after its largest spend is worth more than the same field valued before it.", "The reader should instead have grown the figure at the nominal 10.000000 percent, since the discount rate the owner stated is nominal and the growth follows the stated rate.", "The NPV should have fallen, because a later valuation year discounts every remaining row by one more year.", "A change of date was read as a change of prospects: 77464382.26 is 72534830.66 one year older at 6.796117 percent, with IRR, payback and total unmoved."]'::jsonb, 3, 'Forgetting the capex is a different setting, treat_prior_as_sunk, and it produces 206819768.67, which is nowhere near 77464382.26.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 14, 'AKATA valued from 2030 with prior years sunk reports an NPV of 206819768.67, sunk_net_cash_flow of minus 121123680.00 and a null IRR. Why is the IRR null?', '["With 2029 written off, nothing negative is left in the valued vector to bracket a root.", "The IRR exceeds the 200.0000 percent that the published cases report as the finder''s upper bound, so it is reported as null.", "Newton starts from 10 percent and diverges when the first flow of the vector is positive, and the fallback bisection cannot recover it.", "The engine returns null whenever the NPV exceeds the total net cash flow."]'::jsonb, 0, 'The published valuation_year_sunk case behaves the same way: NPV 37500000.00, IRR null, DPI null, payback Year 0.'),
  ('cashflow', 'intermediate', 'module', 'm02-real-and-nominal', 15, 'treat_prior_as_sunk is set on AKATA with valuation_year left at 2029. What does the engine report?', '["The 2029 capex year is flagged and the NPV becomes 206819768.67, since the flag marks the first row whatever the valuation year.", "Rows flagged sunk 0, sunk_net_cash_flow 0.00 and NPV 72534830.66, because sunk refuses to act without a later valuation year.", "An error, because no row precedes the valuation year and the flag has nothing to mark.", "Both capex years are flagged and total capex reads 0.00, because sunk applies to capital spend rather than to dates."]'::jsonb, 1, 'Sunk is a decision about which question is being asked, and with the valuation year at 2029 the question is still whether to start.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 1, 'AKATA''s discounted_cash_flow column runs minus 121123680.00, 28860006.55, 53279541.38, 40540595.37, 30649858.46, 23167486.48 and 17161022.43. How is the NPV of 72534830.66 obtained from it?', '["Sum the column and subtract the present value of capex, 250909090.91, since the discounted rows are revenue only.", "Divide the real total of 117362408.71 once by one plus the applied rate, which is what the column sums to.", "Sum the column and deflate the result by 3 percent to the 2029 base year.", "Sum the column. There is no other step."]'::jsonb, 3, 'The first row is the valuation year and is undiscounted; each later row is the real flow divided by one more year at 6.796117 percent, and the sum is the headline.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 2, 'zero_rates_capex_only and jv_loss_unused_at_cessation report take null and discounted take null. Why does the engine refuse a figure?', '["Their royalty and tax rates are zero, so the government''s share is undefined rather than nil.", "The pre-take value, revenue less capex less opex, is not positive, so there is no residual to share.", "Their payback is beyond project life, and take is only computed for fields that have paid back.", "Their NPVs are negative, minus 69090909.09 and minus 50000000.00, and a share of a negative value is reported as null."]'::jsonb, 1, 'Take is the government''s part of the pre-take value, 66.1723 percent on AKATA; with nothing to divide it refuses to exist.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 3, 'Summing AKATA''s discounted column as you go, the running total has only just turned positive through 2032, and the last three rows, 30649858.46, 23167486.48 and 17161022.43, supply almost all of the 72534830.66. What does that imply for the profile?', '["AKATA''s value lives in its late years, the rows a higher rate punishes most, so its profile falls steeply.", "The profile is nearly flat, because the tail rows are small and a rate change removes little from small rows.", "The profile rises with the rate, because the 2029 row is the largest in magnitude and is untouched by discounting.", "The profile is unaffected by the tail, since payback is reached during 2032 and later rows are invisible to it."]'::jsonb, 0, 'From 5 to 10 percent the profile falls from 83023565.60 to 55805775.02, more than the drop from 15 to 20.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 4, 'jv_analytic_decision_kpis has an applied rate of 10.000000 percent and its profile point labelled 10 reads 21590909.09, the headline, gap 0.00. On AKATA the point labelled 6.8 reads 72513070.98 against a headline of 72534830.66. Why does AKATA miss?', '["The profile is evaluated on the nominal flows while the headline uses the real ones, and the two differ by the deflator.", "The profile point is evaluated under mid-year discounting and the headline under end-year.", "The engine labels and evaluates the applied point at the rate rounded to two decimals, 6.8 instead of 6.796117, and the slightly higher rate discounts harder.", "The headline carries the 2029 row at full value and the profile discounts it by the rounded rate."]'::jsonb, 2, 'The engine''s own npv() at the exact 6.796117 percent on the same flows returns 72534830.66, so the headline is right and the profile point is the one at the wrong rate.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 5, 'The profile gap is minus 21759.68 on AKATA, minus 40996.42 on multiyear_pia_real and minus 453.74 on allowance_cap_midyear. Why is it always negative?', '["Rounding 6.796117 up to 6.8 percent discounts every row a little harder, so the point always sits below the headline.", "The profile leaves out the valuation year row, and a missing negative row would raise the point rather than lower it, so the sign shows the missing row is positive.", "Floating point accumulation over seven rows drifts downward, and the drift scales with the size of the flows.", "The profile is evaluated end-year and the headline mid-year, and the half-year shift always removes value."]'::jsonb, 0, 'The gap scales with the size of the field, which is why the 203250580.21 case loses 40996.42 and the 2406447.46 case loses 453.74.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 6, 'The profile samples 0, 5, 8, 10, 12, 15 and 20 percent plus the applied rate. What can it not show?', '["Rates below 5 percent, because the 0 percent point is the undiscounted total and not a discounted reading.", "The nominal basis, since the profile is always evaluated on the real flows even when the basis is nominal.", "Any rate above the applied one, because the engine stops sampling once the headline has been reproduced.", "The IRR, which is never a sampled point, and any turn of the curve between samples."]'::jsonb, 3, 'AKATA is still 16026160.80 at 20 percent and its IRR of 29.2361 percent lies beyond the last sampled point, unseen by the profile.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 7, 'AKATA''s nominal running total is minus 24909427.73 at the end of 2031 and 29050104.71 at the end of 2032, and payback_years is 3.461632. A reader interpolates on the displayed cumulative_cash_flow column, minus 29534809.71 to 19845806.34, and lands later. Why?', '["The reader forgot to discount, and the engine''s payback is read on the discounted column, which crosses at 3.961607 years.", "The engine reads payback on the nominal running total against the nominal 2032 flow of 53959532.44, while the displayed column on a real basis run is the real running sum.", "The displayed column carries depreciation of 25500000.00 a year that the payback calculation adds back.", "The reader should have interpolated against the 2033 flow, because the crossing is dated to the end of the year it occurs in."]'::jsonb, 1, 'A real total, a nominal total and a discounted total each cross in a different place, and only the nominal one is the reported payback.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 8, 'AKATA pays back at 3.461632 years and discounted at 3.961607, half a year later on the same rows. What makes the discounted crossing later?', '["Discounted payback is measured from the valuation year rather than from the first row, which adds the half year.", "The discounted crossing is read on the real column, whose 2032 row of 49380616.06 is smaller than the nominal.", "Every row after 2029 has been reduced, so the 2032 discounted row of 40540595.37 closes the shortfall only near the end of the year.", "The 2029 row is discounted as well, which deepens the hole the later rows must fill."]'::jsonb, 2, 'multiyear_jv_real reads 2.889357 and 3.165997 and jv_analytic_decision_kpis 1.333333 and 1.366667; the discounted figure is never earlier.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 9, 'AKATA is switched from end-year to mid-year discounting. What happens to its discounted payback?', '["It moves half a year later, because every exponent has been shifted by half.", "Nothing; it is 3.961607 years under all four combinations of basis and convention.", "It moves earlier, because the 2029 capex shrinks to minus 115486897.55 and the hole is shallower.", "It becomes 3.461632 years, because mid-year timing removes the gap between the two paybacks."]'::jsonb, 1, 'The mid-year shift scales every discounted row by one factor, and a crossing does not move when everything is scaled together.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 10, 'valuation_year_sunk reports payback Year 0 and 0.000000 years. What does that reading mean?', '["The only negative row was declared sunk, so the metric never saw it and the first visible row is already positive.", "The field recovered its capex of 50000000.00 within the first year of production, which a two-year ledger makes possible.", "The payback was measured backward from the valuation year of 2031, and the crossing sits at the valuation date.", "The sunk flow of minus 12500000.00 was counted as recovered at the moment it was written off."]'::jsonb, 0, 'single_year_positive reads Year 0 for the honest reason, a first row of 35000000.00; the sunk case reads it because its capex year of minus 12500000.00 left the metric''s sight.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 11, 'AKATA''s DPI is 0.289088, which is 72534830.66 over 250909090.91. Why is the denominator not the 255000000.00 of capex spent?', '["Depreciation already claimed by 2030, the 21000000.00 of 2029, is removed from the capex before the ratio is taken.", "The denominator is the capex net of its sunk portion, and the engine treats the sanction year spend as partly sunk.", "The denominator is capex less the 2035 tail, which the discount treats as abandoned.", "The denominator is the present value of capex at the same rate and convention as the numerator, so the 2030 spend of 45000000.00 is discounted one year."]'::jsonb, 3, 'For every unit of capital, in present value, AKATA returns 0.289088 units of value beyond the discount rate.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 12, 'A report relabels the engine''s DPI as the profitability index. What is wrong with that?', '["Nothing, provided the report adds one to the DPI, since the profitability index is the DPI plus one by construction: NPV over the PV of capex becomes the PV of inflows over the PV of capex once the capital of 250909090.91 is added back to the numerator, and the two ratios then agree to the cent.", "Nothing; the two are the same ratio and differ only in whether the answer is printed as a fraction or a percentage.", "The engine''s DPI is NPV over the PV of capex, so a project that exactly earns its rate scores zero where the textbook index scores one, and adding one does not recover the index because the textbook denominator holds every outflow, opex included.", "The profitability index uses undiscounted capex of 255000000.00 in the denominator, so the relabelled figure is too high: the engine discounts the 2030 spend of 45000000.00 by one year to reach 250909090.91, and dividing by the smaller present value inflates the ratio beyond what the textbook index prints for the same field."]'::jsonb, 2, 'AKATA''s opex of 183899092.34 sits inside the NPV here and would sit in the denominator there; the engine prints no profitability index.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 13, 'multiyear_pia_real has an NPV of 203250580.21 and a DPI of 0.398389; multiyear_jv_real has an NPV of 88104639.00 and a DPI of 0.598241. Which ranks first?', '["It depends on the constraint: if capital is scarce the second does more per unit of capital, and if it is not NPV ranks and the first wins.", "The first, because NPV is the only ranking and DPI is a description that cannot reverse it.", "The second, because a higher DPI means a higher return on any measure, whatever the capital available: DPI is NPV per unit of capital, and a ratio that beats another per unit beats it in total as well.", "The first, because its PV of capex of 510181818.18 is larger and larger fields carry less risk per unit, so the rate they should be read at is lower and their NPV is understated at 6.796117 percent."]'::jsonb, 0, 'NPV ranks by value; DPI ranks by value per unit of capital, and the two rankings disagree on these two fields.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 14, 'AKATA''s take is 66.1723 percent undiscounted and 76.1610 percent discounted. Why is the discounted figure higher?', '["Tax at 40 percent compounds at the discount rate, so its present value grows relative to the contractor''s share.", "The government''s share arrives earlier: royalty is taken from the first barrel in 2029, while the contractor''s running total is negative until 2032 and is recovered in the tail years that discounting reduces most.", "Discounting reduces the capex of 255000000.00 more than it reduces revenue, which enlarges the residual the government shares: the capex sits in 2029 and 2030, where the exponents are the largest in the ledger, so its present value of 250909090.91 loses the most and the pre-take value grows.", "The discounted take is computed at the nominal 10 percent and the undiscounted at the real 6.796117 percent, and the harsher rate raises it: the two takes are read on different bases, so the gap between 66.1723 and 76.1610 is the Fisher gap between the two rates and has nothing to do with timing."]'::jsonb, 1, 'Every published case with a tail shows the same direction, multiyear_jv_real 69.2573 against 75.4578; single_year_positive, with one row, reads 61.1111 percent both ways.'),
  ('cashflow', 'intermediate', 'module', 'm03-net-present-value', 15, 'AKATA''s royalty is 15 percent and its tax rate 40 percent in every run, yet take reads 66.1723 percent at a working interest of 100, 74.6292 at 75 and 91.5431 at 25. What is take measuring?', '["The government''s share of the contractor''s own net cash flow, which rises as the contractor''s flows shrink with working interest.", "The royalty and tax rates combined, restated on a residual that capex has already reduced, which is the same at every working interest because the 15 and 40 percent are the same at every working interest.", "The government''s share of revenue, which grows because royalty is charged on the whole field and tax on the partner''s share only.", "The share of the whole field''s pre-take value that does not reach your ledger, which at a partial interest includes the partners'' share."]'::jsonb, 3, 'A take quoted without its working interest, like an NPV quoted without its convention, is not comparable to anything.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 1, 'AKATA reports NPV 72534830.66 end-year and 70188970.32 mid-year on the real basis, and 69159247.46 mid-year on the nominal basis. What does the IRR read across those three runs?', '["29.2361 percent end-year, and a lower root under mid-year, because the half-year shift discounts every receipt harder and the curve crosses zero sooner.", "29.2361 percent on the nominal basis and 6.796117 percent on the real basis, since the real run discounts at the applied real rate.", "29.2361 percent in every one of them.", "Three roots, one per NPV."]'::jsonb, 2, 'The IRR is solved from the nominal flow vector alone, and neither the basis, the convention nor the discount rate enters that vector.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 2, 'AKATA''s NPV falls from 72534830.66 at 100 percent working interest to 18133707.67 at 25 percent, and the IRR stays at 29.2361 percent. Why?', '["Scaling every entry of a vector by one factor scales its NPV at every rate and leaves the zero where it was.", "The IRR is solved on the field-level revenue rows, which a joint venture working interest never scales, so it cannot see the interest at all.", "The take rises from 66.1723 to 91.5431 percent as the interest falls, and the extra take exactly offsets the smaller share in the root.", "The engine solves the IRR before the working interest is applied in the cascade."]'::jsonb, 0, 'The take and the NPV are readings of size, and the IRR reports none of that: 18133707.67 and 72534830.66 sit under one root.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 3, 'loss_making, [-1000, 500, 400], reports an IRR of -6.9926 percent. How should that be read?', '["As a failed Newton estimate that should have returned null, since the NPV is -100.00 at 0 percent and negative at every positive rate, so nothing brackets a root.", "As a sign error in the report, because the vector never recovers its 1000 of outlay and a return on it cannot carry a minus sign.", "As the rate at which the undiscounted total of the vector reaches zero, which is the payback reading rather than a root of the curve.", "As a legitimate root: the rate at which a shrinking discount makes the receipts worth exactly the outlay."]'::jsonb, 3, 'The sampled curve reads 49.382716 at -10 percent and -100.000000 at 0 percent, so the crossing had to lie between them before any finder ran.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 4, 'AKATA is on the real basis, so its discounted rows are the real flows 30821366.21 and 60767504.07. Which rate is its IRR of 29.2361 percent built to be compared against?', '["The applied real rate of 6.796117 percent, because that is the rate the real flows are discounted at and the IRR is a root of the same discounted column.", "The nominal 10 percent, because the IRR zeroes the vector printed in money of the day, not the real flows.", "Either rate, since the two bases give the same NPV of 72534830.66 end-year and therefore the same root.", "The inflation rate of 3 percent, since the Fisher relation joins the two rates through it."]'::jsonb, 1, 'At the breakeven price of 64.916777 USD/bbl, where NPV is zero, the IRR reads 10.0002 percent: the nominal rate, which is the proof of which comparison it was built for.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 5, 'late_payout, [-1000, 0, 0, 0, 0, 2500], reports a root of 20.1124 percent and prints the NPV there as -0.000000. What does that residual say?', '["Newton overshot on the flat part of the curve and the bisection fallback ran instead, which always leaves its residual on the negative side of zero.", "The root actually sits between the sampled 4.693930 at 20 percent and -180.800000 at 25 percent, and the engine reports the midpoint of that bracket.", "The engine prints the NPV at every reported root as a negative number, because the root is approached from above by convention.", "The finder stops at a tolerance, not at an exact zero, and the rounded residual landed on the negative side."]'::jsonb, 3, 'Every reported root carries 0.000000 or -0.000000: conventional_five_year at 15.2382 percent and tiny_return at 0.1000 percent print the same kind of residual.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 6, 'The method statement says Newton falls back to bisection when unconverged and returns null when no sign change brackets a root. What does bisection need before it can run?', '["Two rates with NPVs of opposite sign.", "Every root of the curve, so that it can halve the interval between the two nearest and confirm that Newton reached the right one.", "A vector with more than one sign change, on which it picks the root nearest zero on the positive side as the hurdle-rate answer.", "A Newton estimate to refine."]'::jsonb, 0, 'two_roots_minus73_and_173 reads -6500000.000000 at -75 percent and 26500000.000000 at -50 percent, and that pair is a bracket; a curve that never changes sign gives it nothing.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 7, 'no_real_root, [-1, 3, -3], changes sign twice, and its sampled curve reads -271.000000 at -90 percent, -1.000000 at 0, -0.250000 at 100 and -0.333333 at 200. Why is its IRR null?', '["Two sign changes mean two roots, and the engine refuses to choose between them.", "Newton stepped from 10 percent into the region below -90 percent where the last entry dominates, and an unconverged Newton returns null.", "The curve rises toward zero, touches nothing and falls back, so no sign change ever gives bisection a bracket.", "The total at 0 percent is -1.00, and the finder is not run on a vector that never returns its outlay."]'::jsonb, 2, 'Null here means no rate zeroes the vector, not that the vector is bad or good: it says nothing more than that the search found no crossing.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 8, 'AKATA at 30 USD/bbl reports IRR null beside an NPV of -169873348.04. AKATA valued from 2030 with 2029 sunk reports IRR null beside an NPV of 206819768.67. What tells those two nulls apart?', '["The IRR field carries a reason with the null, all negative in the first case and no outlay in the second, and the reader is expected to quote it.", "Only the NPV beside each null: one vector is negative everywhere sampled and the other, with its one negative row removed, is all positive like [5, 5, 5].", "The sunk null is an error, since a field worth 206819768.67 must have some rate at which that value would vanish.", "The price null would become a root if the search were widened below -90 percent, and the sunk null would not."]'::jsonb, 1, 'The engine refuses to distinguish the reasons in the field it returns: all positive, all negative and never crossing all read null.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 9, 'AKATA with a 200000000 abandonment in 2035 reports IRR null; with a 60000000 abandonment it reports 23.2570 percent. What made the difference?', '["With 200000000 the NPV is negative at every sampled rate, -58362170.82 at 0 percent, so nothing brackets a root; with 60000000 it is 81637829.18 at 0 percent and -78880508.48 at 100.", "A terminal negative always returns null, and the 60000000 case escaped only because its last flow of -29598201.95 is smaller than the 2034 flow that precedes it.", "Newton from 10 percent overshoots on the steeper curve of the larger abandonment, and an unconverged Newton returns null without running the fallback.", "The larger abandonment exceeds the 255000000.00 of capex it is set against, and the engine refuses a root on a vector whose outlay is not recovered."]'::jsonb, 0, 'Both vectors end in a negative and both change sign twice; the sign of the curve between the ends, not the shape of the vector, decides whether there is a crossing.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 10, 'two_roots_2_and_6, [-100, 208, -108.12], has an NPV of -0.120000 at 0 percent, 0.036982 at 4 and -0.264463 at 10. The engine reports 6.0000 percent and the golden holds 2.0000. Why does the engine land on 6?', '["The engine takes the larger root by rule, on the reasoning that a project''s return is the highest rate at which its value is still not negative.", "The curve prints -0.000000 at 2 percent, and the engine rejects any candidate whose residual sits on the negative side of zero.", "6 is the root nearest zero on the positive side, in the hurdle-rate region, which is the rule the method statement gives.", "Newton starts at 10 percent, where the curve reads -0.264463 and rises toward the root at 6, so that is the crossing it reaches."]'::jsonb, 3, 'The oracle reports the root nearest zero on the positive side and the engine the root Newton reaches from 10 percent; the case records the choice as an owner decision not yet made.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 11, 'A reader takes three_roots_0_7_33''s reported IRR of 7.3509 percent to a hurdle of 5 percent and approves. What went wrong?', '["The reader should have used the oracle''s 0.0000 percent, which is below 5, and rejected the vector on the smaller root.", "Nothing, since 7.3509 sits above the hurdle and the curve reads 0.081930 at 30 percent.", "The NPV at 5 percent is -0.028075, negative; a hurdle comparison needs the sign of the curve at the hurdle, which is the NPV, not a root.", "The engine should have reported 33, the largest root, and the reader should compare that with the hurdle instead."]'::jsonb, 2, 'On two_roots_2_and_6 the same reasoning happens to hold because the NPV at 5 percent is 0.027211, positive; the reasoning is wrong either way, and only the sign at the hurdle is an answer.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 12, 'Why must a vector whose last entry is negative cross zero an even number of times, as two_roots_2_and_6 does?', '["Because the count of roots equals the count of sign changes in the vector, and a terminal negative after a positive middle makes two.", "At very negative rates the factor on the last entry is enormous and drags the NPV down, -8832.000000 at -90 percent; at very high rates the NPV tends to the first entry, -100; negative at both ends and positive between means an even count of crossings.", "Because Newton and bisection each find one root, and the engine runs both on a terminal-negative vector.", "Because the terminal negative is discounted less than the outlay, making the curve symmetric about its peak at 4 percent."]'::jsonb, 1, 'no_real_root ends negative too and crosses zero times, which is also even: the argument fixes the parity of the count, not the count.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 13, 'jv_analytic, [-12500000, 37500000], reports IRR 200.0000 percent and NPV 21590909.09 at 10 percent. AKATA reports 29.2361 percent and 72534830.66 at the same nominal 10 percent. A reader sorts the two by IRR. What has been measured?', '["How steeply each curve falls through zero, not how high it stands at the chosen rate; NPV ranks AKATA ahead.", "The same thing either way, because both numbers are readings of one curve and the rankings must agree whenever the discount rate is the same on both sides.", "Value per unit of capital, since 200.0000 percent reflects a 50000000.00 capex recovered in a single year against AKATA''s 255000000.00.", "The payback of each field, which is why jv_analytic at 1.333333 years ranks first."]'::jsonb, 0, 'IRR refuses to report scale: 200.0000 percent sits beside 21590909.09 and 29.2361 percent beside 72534830.66, and the steeper curve is the smaller field.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 14, 'On the published multiyear_jv_real sweep the nominal discount rate runs from 0 to 20 percent and NPV falls from 148905488.72 to 50852201.45. What does the IRR read at the 20 percent point?', '["A root below 47.9020 percent, because the sweep at 20 percent applies a real rate of 16.504854 percent and the curve is read on harder-discounted flows.", "Null, since at 20 percent nominal the NPV has fallen to a third of its 0 percent value and the sampled curve no longer brackets a positive root.", "16.504854 percent, the real rate.", "47.9020 percent, as at every other point."]'::jsonb, 3, 'The discount rate is the yardstick brought to the curve; the IRR is the property of the curve, and the sweep never touches the rows the curve is built from.'),
  ('cashflow', 'intermediate', 'module', 'm04-the-internal-rate-of-return', 15, 'A manager asks whether AKATA survives a discount rate of 15 percent. Which single number answers, and what does the IRR of 29.2361 percent contribute?', '["The NPV profile point at 15 percent, 33900281.71, since the profile is the sensitivity to the rate and 15 is one of its sampled points on the real flows.", "The IRR alone, because 29.2361 percent is the field''s return and any rate below it is survived by definition.", "The NPV at a nominal 15 percent, read from the discount rate sweep; the IRR only says how far the rate can rise before that NPV reaches zero.", "The discounted payback at 15 percent, since a rate the field survives is one at which it still pays back inside its life."]'::jsonb, 2, 'The profile at 15 is on the real flows, where 15 is not a nominal 15; the sweep row is the reading at the rate the manager named, and the IRR answers how wrong the rate could be, not what the value is.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 1, 'AKATA''s price sweep runs from 30 to 120 USD/bbl and reports NPV, IRR, payback and take at nine prices. What is each point of the sweep, mechanically?', '["One ledger with its revenue column rescaled by the ratio of the new price to 82, and the royalty and tax columns rescaled with it.", "The base ledger with the oil price escalator moved so that the 2 percent path passes through the sweep price in 2030.", "A separate full run of the whole ledger with the flat oil_price_usd_bbl moved and every other input held still.", "A point on a probability curve, weighted so that the nine NPVs average to an expected value."]'::jsonb, 2, 'Nine ledgers at nine flat prices, each with the 2 percent escalator on top: at 82 the 2030 applied price is already 83.640000, and each price carries its own tax column.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 2, 'AKATA at 50 USD/bbl reports a take of 135.2824 percent. What does a take above 100 percent mean?', '["The royalty is charged on revenue regardless while the pre-take value is small, so the government keeps more than the whole; the contractor''s real net cash flow totals -45016230.39.", "A rounding fault in the take denominator, which the engine leaves unflagged when the pre-take value is small.", "The royalty at 15 percent and the tax at 40 percent have stacked on one base, which the cascade should have prevented since they cannot exceed 55 combined.", "The sweep reused the royalty column from the 82 USD/bbl run against the smaller revenue at 50 USD/bbl."]'::jsonb, 0, 'A take above 100 percent is a royalty on a loss, not an error; at 45 USD/bbl it reads 247.7770 percent for the same reason.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 3, 'AKATA at 40 USD/bbl and below reports take as null, while at 45 it reports 247.7770 percent. Why does the take vanish there?', '["The IRR at 40 USD/bbl is -21.3703 percent, and a take is suppressed whenever the root is negative.", "The tax column at 40 reads 13834880.00, 7217644.80 and 2950616.45 and then zeros, and a take needs a tax payment in every year of the ledger.", "Payback reads Beyond project life at 40, and the take is defined only inside the payback period.", "A share of a pre-take value that has stopped being positive is not reported."]'::jsonb, 3, 'The null and the 247.7770 sit either side of one line: the pre-take value, revenue less capex less opex, crossing zero between 40 and 45 USD/bbl.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 4, 'At 50 USD/bbl AKATA''s tax column runs 21314880.00, 13633444.80, 8433524.45, 3963295.68, 79525.71, 0.00, 0.00. Why do the last two years pay nothing?', '["The economic limit trimmed those two years from the valued ledger, and a trimmed year carries no tax.", "Depreciation of 25500000.00 and the escalated opex outrun the revenue, so there is no positive taxable income to tax.", "The loss carried forward from the first year is used up against the last two years, since the royalty at 15 percent left no taxable income in 2029.", "The royalty at 15 percent takes the whole of the late-year revenue once the price falls this far."]'::jsonb, 1, 'At 30 USD/bbl only the first two years pay, 6354880.00 and 801844.80, and total tax falls to 7156724.80: the price moves the year in which the deductions overtake the revenue.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 5, 'On the published oil_price_multiyear_pia_real sweep the take reads 144.0232 percent at 40 USD/bbl, 71.1024 at 80 and 71.3286 at 120, while AKATA''s JV take falls from 87.4083 at 60 to 57.9418 at 120. Why does the PIA take hold almost flat?', '["The PIA take is working-interest invariant, so it cannot move with the price either.", "The PIA field''s unit technical cost is 32.823299 USD/boe at every point, so cost and price scale together and the ratio is fixed.", "The PIA''s price royalty tiers rise with price, so the government''s share grows as the pre-take value grows.", "The PIA cascade charges its taxes on revenue rather than on income, so the take is a rate rather than a share."]'::jsonb, 2, 'Both takes are shares of a residual; the JV share falls because a fixed royalty and a fixed tax rate take a smaller fraction of a growing residual, and the PIA tiers replace that fixed royalty with one that climbs.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 6, 'An analyst averages AKATA''s nine sweep NPVs, from -169873348.04 at 30 USD/bbl to 231658748.27 at 120, and reports the mean as the expected value. What is wrong?', '["The average must be taken over the discounted flows before the ledger is summed, not over the NPVs afterwards.", "The sweep is on the flat price only, so the mean ignores the 2 percent escalator that the engine adds on top at each price.", "The sweep should have been weighted by the take at each price, since the government''s share changes from 57.9418 to null across it.", "Each NPV says what the field is worth if the price is that number for the whole life, and the sweep says nothing about how likely any price is."]'::jsonb, 3, 'Nine ledgers at nine flat prices are nine conditional answers, and averaging them is not an expected value because no probability was ever attached to a price.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 7, 'At a nominal discount rate of 0 percent AKATA''s rate sweep prints NPV 141637829.18, the nominal total, not the real total 117362408.71, and an applied real rate of -2.912621 percent. Why?', '["A nominal rate under the 3 percent inflation is a negative real rate, and discounting the real flows at a negative rate inflates them back to money of the day.", "At 0 percent the engine switches to the nominal basis, since a real rate cannot be derived from a nominal rate of zero.", "The sweep is run on the nominal flows because the swept rate is nominal, whatever basis the case is configured on.", "The real total is the profile''s 0 percent point, and the sweep rounds the Fisher rate differently from the profile."]'::jsonb, 0, 'The applied real rate passes through zero between 2 and 4 percent nominal, and only from there does discounting on the real basis begin to shrink the real flows.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 8, 'AKATA''s NPV at a nominal discount rate of 8 percent is 83912631.29. Its inflation sweep, at a fixed 10 percent nominal, reports a real total net cash flow of 83912631.29 at 8 percent inflation. Why the same number?', '["Because 8 percent inflation at 10 percent nominal gives the same applied real rate as 8 percent nominal at 3 percent inflation.", "Because dividing each nominal flow by the same factor per year is deflation when 8 percent is the inflation rate and discounting when it is the discount rate.", "Because the Fisher relation holds NPV at 72534830.66 whatever the inflation, so any 8 percent reading maps back to one real figure.", "Because the two sweeps share one set of rows, and any two KPIs read from the same rows at the same percentage must agree."]'::jsonb, 1, 'The applied rates are 1.851852 percent in one run and 4.854369 in the other, so it is not a coincidence of rates; it is the same arithmetic wearing two names, and the 2 percent row, 125059129.50, matches the same way.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 9, 'discount_rate_multiyear_jv_real reruns its eight-year JV field at nominal rates from 0 to 20 percent in steps of 2. Which of its printed readings hold the same value on every row of the sweep?', '["The discounted payback and the DPI, because both are ratios of present values that were scaled together.", "The NPV profile, since it is sampled at fixed rates of 0, 5, 8, 10, 12, 15 and 20 percent and does not read the configured rate.", "The applied real rate, which stays at 6.796117 percent because inflation is fixed at 3.", "IRR 47.9020 percent, payback 2.89 years, take 69.2573 percent, total revenue 767745022.67 and total tax 181905488.72."]'::jsonb, 3, 'The rows are the same on every row of the sweep and only the exponent changes, so every undiscounted KPI holds and every discounted one moves.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 10, 'AKATA''s breakeven is 64.916777 USD/bbl. Rerun at that price, the NPV is 897.16 USD, the IRR 10.0002 percent and the take 79.0146 percent. What is the 897.16?', '["The profile rounding gap at the applied rate, the same defect that puts 72513070.98 against 72534830.66 at the base price, carried into the search because the search reads the profile point at 6.8 percent rather than the headline.", "Proof that the NPV curve against price never quite crosses zero, so 64.916777 is the nearest price rather than a root.", "The trace of a search that stops at a tolerance on price: nothing for a decision, something for a reader who expected zero.", "The mid-year against end-year difference at the breakeven price, which the search cannot remove."]'::jsonb, 2, 'The published cases leave the same trace, -243.53 on jv_analytic, 810.98 on pia_worked_example and 851.16 on multiyear_pia_real, and the IRR of 10.0002 percent confirms the crossing was found.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 11, 'AKATA''s breakeven reads 64.916777 USD/bbl as configured, 64.916777 at a working interest of 60 percent, 69.518418 at a 15 percent discount rate and 74.945115 with royalty 20 and tax 50 percent. Why does the working interest leave it unmoved?', '["Scaling every flow by one factor leaves the zero of NPV against price where it was.", "Under joint venture terms the working interest scales only royalty, taxable income, tax and net cash flow while revenue stays at field level, and the breakeven is solved on the revenue.", "The search moves the flat price before the working interest is applied in the cascade, so the interest is invisible to it.", "At 60 percent the take is 79.7034 percent, close enough to the 79.0146 at breakeven that the search lands on the same price."]'::jsonb, 0, 'The same argument holds the IRR at 29.2361 percent across every working interest: a zero does not move when the whole curve is multiplied by one number.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 12, 'positive_at_floor_null reports a breakeven of null. What does that null mean?', '["No price in the search turns the NPV positive, so the field never breaks even.", "The configuration carries a price deck, and a field priced by a deck has no single flat price to move.", "The NPV is already positive at the lowest price the search tries, so there is no crossing to bracket.", "The search reached its price tolerance with a residual larger than the 897.16 it accepts on AKATA."]'::jsonb, 2, 'Three nulls, three reasons: deck_present_null has a deck of one entry, never_breaks_even_null never turns positive, and positive_at_floor_null has nothing to bracket because it starts above zero.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 13, 'A reader describes AKATA''s breakeven of 64.916777 USD/bbl as the price at which the field stops losing money. What is the correction?', '["It is the price at which the field stops losing money in money of the day; in real terms the loss continues until the real total turns positive at a higher price, because the 3 percent deflator removes value from every row after 2029 and the real column crosses zero later than the nominal one.", "It is the price at which the field stops losing value at the discount rate; at 60 USD/bbl the real net cash flow already totals 8466495.42, and the zero-total price sits between 50 and 60.", "It is the price at which the IRR reaches 10.0002 percent, which is a property of the curve and not a statement about money at all, so the breakeven is a root-finding artefact that says where the curve meets the nominal rate and nothing about whether the field pays.", "It is the price at which the take reaches 79.0146 percent, the point where the government''s share stops growing."]'::jsonb, 1, 'At 50 USD/bbl the real total is -45016230.39 and at 60 it is 8466495.42, so the zero-total price is only bracketed by the sweep, while the breakeven, solved rather than read off a grid, sits above both at 64.916777.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 14, 'On decline_rate_multiyear_pia at 20 percent decline the limit year is 2030, four years are trimmed and six rows are valued. What does the sweep refuse to do with the trimmed years?', '["Report them at all, so the rows column reads 10 on every point and only the KPIs reveal the trimming, because the row count is fixed by the production upload and the limit test only zeroes the values in the years it fails.", "Charge their opex, so the KPIs of the shortened field carry no cost after the limit year, while the revenue of the trimmed years is still counted inside the total of 1532137562.53.", "Discount them, so they enter the NPV at face value and pull the NPV down to -76483227.81, because a year past the limit is carried undiscounted as a liability instead of being removed from the ledger.", "Keep them: a year that fails the limit test is removed from the valued ledger, not carried at zero, and the KPIs are of the shortened field."]'::jsonb, 3, 'At 40 percent decline seven years are trimmed and three rows survive, and total revenue falls from 3485716284.18 at 5 percent decline to 794617600.00.'),
  ('cashflow', 'intermediate', 'module', 'm05-sweeps', 15, 'The decline sweep reports a take of 1199.4096 percent at 40 percent decline and a unit technical cost of 78.666122 USD/boe. What is the 1199.4096?', '["A share of a pre-take value that has almost vanished, because rows were trimmed while royalties are still charged on what remains.", "A rounding fault in the take, which the engine should have reported as null once the residual turned negative as it does on AKATA at 40 USD/bbl.", "The royalties of 118324626.82 divided by the three surviving rows of revenue, which is how the take is defined once the limit engages.", "The take on the ten-year field before trimming, carried forward unchanged because the take is an undiscounted reading."]'::jsonb, 0, 'Take is 105.7792 percent at 20 percent decline and 202.4061 at 30: the denominator shrinks toward zero as rows are cut, and a share of a value near zero is a large percentage.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The capstone method is worked on AKATA in eight steps. What does step one write, before any number?', '["The headline NPV of 72534830.66, because every later step is a check on it and a check needs its target before the conventions can be chosen.", "The convention sentence: real basis, end-year, 10 percent nominal, 3 percent inflation, valued in 2029, which is the label on every number that follows.", "The IRR of 29.2361 percent, because it is the one reading no convention can move and so it anchors the rest of the readings.", "The nominal flow vector, because the eight steps all read from it and the convention is only needed when a reader asks for it."]'::jsonb, 1, 'Every number changes meaning when a convention is found late; 72534830.66 read as mid-year or as valued from 2030 is a different claim about the same rows.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Step two derives the applied rate for AKATA, real basis, 10 percent nominal, 3 percent inflation. What is applied, and what would the nominal basis apply?', '["The nominal less the inflation, obtained by subtraction, on the real flows; the nominal basis applies the same subtracted rate, because the deflator is taken out of the rate on either basis.", "10.000000 percent on the real flows as printed, because discount_rate_pct is applied as configured on either basis and the basis only decides which total is printed.", "1.851852 percent, the rate the sweep reports at 8 percent inflation, because the escalators of 2 and 3 percent add to the 3 percent inflation before the rate is derived.", "6.796117 percent on the real flows; the nominal basis applies the nominal rate itself, 10.000000 percent, and the end-year NPV is 72534830.66 on both."]'::jsonb, 3, 'The Fisher rate is one plus the nominal over one plus the inflation less one; at 0 percent inflation it would be 10.000000 and at 8 percent 1.851852, and NPV is 72534830.66 at each.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Step three reads AKATA''s NPV under both conventions, 72534830.66 end-year and 70188970.32 mid-year on the real basis. What does the method say to report?', '["The pair with its convention on each, because the pair is the answer and neither number alone is.", "The mid-year figure of 70188970.32, because it is the lower of the two and a decision should rest on the conservative reading.", "The end-year figure of 72534830.66, because the engine defaults to end-year and the default is the engine''s statement of the true convention.", "The mean of the two, because the true timing of cash inside a year lies between the conventions and averaging removes the convention error."]'::jsonb, 0, 'The rows are identical under both readings, and 69159247.46 is the same field mid-year on the nominal basis; no one of the three is more true than the others.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Step four: AKATA valued from 2030 reads 77464382.26 with prior years kept and 206819768.67 with them sunk. What decides which figure is wanted?', '["The sign of the 2029 flow: a negative prior year of -121123680.00 is sunk by definition, and only a positive prior year would be kept.", "The size of the gap: a difference as large as 77464382.26 against 206819768.67 means the sunk run has dropped a row and is the wrong one.", "The question being asked: whether to start keeps 2029, and whether to continue, given that 2029 is paid, sinks it.", "The IRR: the run that still reports 29.2361 percent is the valid one, and the null IRR of the sunk run marks it as a calculation that failed."]'::jsonb, 2, 'Both are correct for their question, and the sunk run reports the 2029 flow of -121123680.00 as sunk_net_cash_flow so the reader can see what was removed.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Step five reads the profile. AKATA''s point labelled 6.8 reads 72513070.98 and the headline is 72534830.66. Which is quoted, and why?', '["The profile point, because it is the charted figure and a chart is what a reader will hold the number against when it is checked.", "The headline, because the point is evaluated at 6.8 percent, the applied 6.796117 rounded to two decimals, and the gap of -21759.68 is the harder discount.", "The 10 percent point, 55805775.02, because the configured discount rate is 10 and the row labelled 10 is the NPV at the configured rate.", "The 0 percent point, 117362408.71, because it is the only point free of the rounding and every other sampled point carries the same gap."]'::jsonb, 1, 'The engine''s own npv() at the exact 6.796117 percent returns 72534830.66, so the headline is right and the profile marker sits a few thousandths of a percent to the right of where it claims to be.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Step six: before trusting AKATA''s IRR of 29.2361 percent, what does the method have you write, and what does it show on the base case?', '["The NPV at 0 percent, 141637829.18, positive, which proves the curve crosses zero exactly once somewhere between 0 and 100 percent.", "The residual at the root, 0.000000, which proves the root is exact and an exact root is therefore the only root.", "The first flow, -121123680.00, negative, which is the outlay the return is a return on and the only sign the count of roots depends on.", "The last nominal flow, 30401798.05, positive, so the curve has one positive root and the reported rate is the only one."]'::jsonb, 3, 'With a 60000000 abandonment the last flow is -29598201.95 and the reported 23.2570 percent is one of two roots; the sign of the last entry is what changes the count.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Six conventions label 72534830.66. Which single change moves it to 70188970.32, and which to 206819768.67?', '["Real to nominal basis moves it to 70188970.32, because the deflator comes out of the rows; a 2030 valuation year with prior years kept moves it to 206819768.67.", "Inflation from 3 to 8 percent moves it to 70188970.32; valuing from 2031 with prior years kept moves it to 206819768.67.", "End-year to mid-year moves it to 70188970.32; a 2030 valuation year with prior years treated as sunk moves it to 206819768.67.", "The nominal rate from 10 to 12 percent moves it to 70188970.32; an abandonment of 60000000 in 2035 moves it to 206819768.67."]'::jsonb, 2, 'Basis does not move NPV end-year, inflation never does on the real basis with the escalators set, 2030 with prior years kept gives 77464382.26, and the 60000000 abandonment gives 38666394.86.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The tier ends on the sentence that IRR is a property of a curve, not of a project. What is the sentence claiming?', '["That the IRR is a zero of one vector''s NPV curve: a curve with two zeros has two IRRs and the engine''s one is a choice, and a scaled vector keeps its IRR at any size.", "That the IRR moves when the convention moves, as NPV does from 72534830.66 to 70188970.32, because the curve is redrawn under mid-year discounting.", "That the IRR is a rate on the project''s money, so a project with an IRR of 29.2361 percent earns 29.2361 percent on its 255000000.00 of capex.", "That the IRR is read from the sampled profile, so AKATA''s 29.2361 percent is where the profile crosses zero between the 15 and 20 percent points."]'::jsonb, 0, '29.2361 percent holds at every working interest and under all four conventions; on [-100, 208, -108.12] the engine reports 6.0000 and the oracle 2.0000, both zeros of one curve.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'AKATA''s flow vector is [-121123680.00, 31746007.20, 64468245.07, 53959532.44, 44874457.77, 37311468.65, 30401798.05]. An abandonment of 60000000 in 2035 is added. Which entry changes, what happens to its sign, and what does that do to the count of IRR roots?', '["The first entry grows to include the abandonment as a provision, stays negative, and the root count is unchanged because only the sign of the first flow matters.", "The last entry becomes -29598201.95, negative, and the root count goes from one to two, of which the engine reports 23.2570 percent.", "The last entry becomes -29598201.95, negative, and the root count goes from one to none, which is why the engine reports null.", "Every entry falls by a share of the 60000000 spread as a sinking fund across the seven years, the signs are unchanged, and the single root moves down to 23.2570 percent."]'::jsonb, 1, 'The 200000000 abandonment takes the last entry to -169598201.95 and the NPV negative at every sampled rate, -58362170.82 at 0 percent, and that is the case with no root at all.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'The onward lesson names a second source of terminal negatives beside abandonment. What is it?', '["A price deck that falls in its last entries, which turns the late revenue rows negative before the cascade is applied to them.", "Mid-year discounting, which discounts the valuation year row and so pushes a negative into the tail of the discounted column.", "A tail kept past its economic limit with the limit test off, where each late year carries a loss to the end of the vector.", "A working interest below 100 percent, which scales the late rows harder than the early ones and turns the tail negative at 25 percent."]'::jsonb, 2, 'At 20 percent decline the limit year is 2030 and four years are trimmed; with the limit off those years would stay, and each would carry a loss.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'The three habits the lesson names end with reading the rows column before comparing two runs. Why that column?', '["Because the rows column carries the sunk flag, and a run with a sunk row reports 206819768.67 where the same rows kept report 77464382.26.", "Because the rows column is where the discounting convention is recorded for each run, end_year or mid_year, and two runs under different conventions cannot be ranked against each other.", "Because the number of rows sets the exponent of the last flow, so a ten-row field is discounted harder than a six-row field at the same rate.", "Because a sweep that trims years compares different fields: at 20 percent decline six rows are valued and at 40 percent three, so the KPIs are of shortened ledgers."]'::jsonb, 3, 'The 10 percent decline point keeps all 10 rows and reads 153012318.45; the 20 percent point reads -76483227.81 with four years gone, and part of that difference is the missing rows.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'What does the capstone method refuse to produce?', '["One number: it produces a labelled set, and a reader asked for the NPV answers with the label attached.", "A mid-year figure, since the engine defaults to end-year and the method follows the engine''s default.", "An IRR on a real basis run, since 29.2361 percent is solved on the nominal flows and the method is worked on the real basis.", "A profile, since the applied-rate point misses the headline by -21759.68 and the method discards any reading it cannot reconcile."]'::jsonb, 0, 'AKATA''s 72534830.66, 70188970.32, 77464382.26 and 206819768.67 are all NPVs of the same rows, and only the label tells them apart.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Working the method on multiyear_jv_real: 127186476.88 at 0 percent, headline 88104639.00 at 6.796117 percent, 88086010.81 at the point labelled 6.8, IRR 47.9020 percent. What is the gap, and what is needed before calling the IRR a single root?', '["The gap is -18628.18, and the residual at 47.9020 percent, which reads 0.000000 whenever the root is unique.", "The gap is 0.00, since this case shares its basis with jv_analytic_decision_kpis where the point equals the headline, and an IRR above 20 percent needs no check.", "The gap is -18628.18, and the sign of the vector''s last flow: a positive last entry gives one positive root and a negative one gives two.", "The gap is -21759.68, the same on every real basis case, and the IRR is single because the sweep reports 47.9020 at every rate from 0 to 20."]'::jsonb, 2, 'The gap scales with the field, -21759.68 on AKATA and -40996.42 on multiyear_pia_real; a residual of 0.000000 proves a root and says nothing about how many there are.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'AKATA''s NPV is -21406234.12 at 60 USD/bbl and 22132715.69 at 70, and the breakeven is 64.916777. What confirms the breakeven, and against which rate?', '["The take rerun at that price reads 79.0146 percent, which is the point where the government''s share stops rising as the price falls.", "The IRR rerun at that price reads 10.0002 percent, the nominal rate: where NPV is zero at the configured rate, that rate is itself a root.", "The NPV rerun at that price reads 897.16, which is zero to the engine''s tolerance, and the applied real rate of 6.796117 percent is the root there.", "The discounted payback rerun at that price reads 3.961607 years, unchanged, and an unchanged discounted payback marks a zero of NPV."]'::jsonb, 1, 'The IRR is compared against the nominal 10 percent and not the applied real 6.796117, and the 897.16 residual is the trace of a search that stops at a tolerance on price.'),
  ('cashflow', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which two numbers does the Professional tier hand on as numbers to distrust, and where does the third come from?', '["The mid-year NPV of 70188970.32 and the sunk NPV of 206819768.67; the third is the applied real rate of 6.796117 percent, which a subtraction of 3 from 10 would misstate as a higher rate than the Fisher relation gives.", "The take of 135.2824 percent at 50 USD/bbl and the null IRR at 30 USD/bbl; the third is the breakeven residual of 897.16.", "The profile gap of -21759.68 and the breakeven residual of 897.16; the third is AKATA''s IRR of 29.2361 percent, which is one of two roots.", "The profile gap of -21759.68 and the two-root IRR of [-100, 208, -108.12], engine 6.0000 against oracle 2.0000; the third belongs to the Expert tier and concerns abandonment."]'::jsonb, 3, '70188970.32 and 206819768.67 are correct readings under their labels; the numbers to distrust are the ones the engine reports without saying what it did to get them.'),
  ('cashflow', 'intermediate', 'final', null, 1, 'AKATA''s 2033 nominal flow of 44874457.77 reaches 30649858.46 in the discounted column on both bases. By which two routes?', '["At 10.000000 percent on the nominal flow, or at the same 10.000000 percent on the real flow of 39870374.51, since the rate is the configured one on either basis.", "At 6.796117 percent on the nominal flow, or at 10.000000 percent on the deflated flow, because the harsher rate must go with the smaller number to land on one value.", "At 10.000000 percent on the nominal flow, or deflated over four years of 3 percent to 39870374.51 and then discounted at 6.796117 percent.", "At 10.000000 percent on the nominal flow, or at the nominal less the inflation on the real flow, which is what the Fisher relation reduces to over four years."]'::jsonb, 2, 'Deflating the flow and deflating the rate multiply back to one factor, which is why the two bases agree at 72534830.66 end-year.'),
  ('cashflow', 'intermediate', 'final', null, 2, 'Under mid-year discounting on the nominal basis AKATA''s 2029 row reads -115486897.55 in the discounted column instead of -121123680.00. What happened to the valuation year row?', '["It was shifted by half a year like every other row, so the capex is divided by the square root of 1.1 even though it sits in the valuation year.", "It was deflated by half a year of the 3 percent inflation, because mid-year timing moves the base date for the real column as well.", "The 45000000.00 of 2030 capex was netted into it, since mid-year timing brings the following year''s spend forward by half a year.", "Nothing was discounted; the row is printed net of its 2029 depreciation of 21000000.00 under mid-year, and the exponent is still zero in the valuation year."]'::jsonb, 0, 'The whole column is scaled by one factor, which is why the mid-year NPV of 69159247.46 sits closer to 72534830.66 than a reader who shifts only the revenue years would compute.'),
  ('cashflow', 'intermediate', 'final', null, 3, 'mid_year_discounting reports NPV 20586124.09 against 21590909.09 for its end-year twin, yet DPI 0.431818 and discounted take 82.2761 percent are identical in both. What separates the readings that move from those that hold?', '["The DPI and the take are undiscounted readings, so the convention has no exponent to shift in them.", "The mid-year shift applies to the 2031 row only, and the DPI and the take are read on the 2030 row where nothing moved.", "The NPV is evaluated on the real flows and the ratios on the nominal flows, and the convention touches only the real column.", "A sum of present values moves when every row is scaled by one factor; a ratio of two present values scaled by the same factor does not."]'::jsonb, 3, 'The same reasoning holds AKATA''s discounted payback at 3.961607 years under all four combinations of basis and convention.'),
  ('cashflow', 'intermediate', 'final', null, 4, 'A summary table lists two projects at 203250580.21 and 196677221.27. What is a reader entitled to conclude from those two figures?', '["That the second project is worth less, since NPVs on the same ledger scale are directly comparable whatever their convention.", "Nothing until the conventions are attached: they are one field, multiyear_pia_real, read end-year and mid-year.", "That the second project carries the higher discount rate, since a lower NPV on a similar field is the mark of a harsher rate.", "That the two differ by a valuation year, since a shift of one year at 6.796117 percent is about the size of the gap."]'::jsonb, 1, 'At 5 percent their profiles read 222922734.92 and 217550313.27, and every difference between the two columns is the half-year shift.'),
  ('cashflow', 'intermediate', 'final', null, 5, 'AKATA''s configuration has discount_rate_pct 10 and inflation_rate_pct 3 and the basis is real. Which rate does the engine apply, and to which column?', '["10 percent to real_net_cash_flow, because discount_rate_pct is the rate applied and the basis only selects the column it is applied to.", "6.796117 percent, derived by Fisher from the two, to real_net_cash_flow; the 10 would be applied to net_cash_flow on the nominal basis.", "3 percent to net_cash_flow to produce the real column, and then 10 percent to the real column, which is two discounts in sequence.", "The nominal rate plus the inflation to net_cash_flow, because a nominal flow carries inflation that the rate must remove."]'::jsonb, 1, 'Both routes give the same discounted column, 30649858.46 for 2033, and the same NPV of 72534830.66 end-year.'),
  ('cashflow', 'intermediate', 'final', null, 6, 'AKATA''s 2029 capex of 210000000.00 might have been spent in January or in December. How does the engine time it?', '["It reads the month from the capex upload and discounts a December spend by a further eleven twelfths of a year.", "It assumes January for capex and December for revenue, which is why capex is barely discounted and revenue is discounted hard.", "It spreads the 210000000.00 evenly across the year, which is what the mid-year convention computes exactly.", "At one instant, the same for both, fixed by the convention: the end of 2029 under end-year, the middle of the year under mid-year."]'::jsonb, 3, 'Every flow in a row arrives at one instant; the convention offers end_year and mid_year and nothing else, and refuses quarterly or split timing.'),
  ('cashflow', 'intermediate', 'final', null, 7, 'AKATA''s inflation is raised from 3 to 8 percent with the escalators left as configured. Which printed figures move?', '["The real total net cash flow, 117362408.71 to 83912631.29, and the applied real rate, 6.796117 to 1.851852 percent; no ledger row and not the NPV.", "The gross revenue rows, because a higher inflation lifts the applied oil price above 92.345318 in 2035, and the NPV with them.", "The NPV, which falls as the deflator grows, and the real total with it, while the applied real rate stays at 6.796117 percent.", "The nominal total net cash flow, 141637829.18, which is restated in the new money of the day, while the real total holds."]'::jsonb, 0, 'The escalators write the rows and are set explicitly on AKATA, so inflation only deflates, and the deflated flows at the deflated rate give 72534830.66 every time.'),
  ('cashflow', 'intermediate', 'final', null, 8, 'At 5 percent inflation and 10 percent nominal the engine reports an applied real rate of 4.761905 percent. Why not 5?', '["Because the engine rounds the real rate to six decimals after subtracting, and 4.761905 is the rounded form of the subtraction.", "Because the 2 percent price escalators are netted against the inflation before the subtraction, which lowers the result.", "The real rate is one plus the nominal over one plus the inflation, less one, which sits below the subtraction, and the shortfall grows with inflation.", "Because the real rate is the nominal rate deflated over the seven-year life of AKATA, and the deflation compounds."]'::jsonb, 2, 'At 8 percent inflation the applied rate is 1.851852 percent, further from the subtraction than at 5, and a hand calculation at a subtracted rate will not reconcile with 72534830.66.'),
  ('cashflow', 'intermediate', 'final', null, 9, 'In AKATA''s price sweep the point at 82 USD/bbl shows a 2030 applied price of 83.640000. What is the sweep moving?', '["The 2030 price directly, because the sweep is indexed to first production and the 2029 base price is back-calculated from it.", "The escalator, so that the 2 percent path passes through the sweep price in 2030 and the 2029 price is the same at every point.", "The inflation rate, since on the real basis the price a reader sees is the deflated one and 83.640000 is 82 restated.", "The flat oil_price_usd_bbl in 2029 money; the 2 percent escalator is applied on top at every point, so no point is a flat price for the life."]'::jsonb, 3, 'The 2035 applied price at the base point is 92.345318, six years of 2 percent on 82, and a sweep point at 120 escalates the same way.'),
  ('cashflow', 'intermediate', 'final', null, 10, 'Valued in 2029, 2030 and 2031 with nothing sunk, AKATA reads 72534830.66, 77464382.26 and 82728951.93. At what rate is the NPV growing, and why that rate?', '["At the nominal 10 percent a year, because a valuation year compounds prior flows forward in money of the day.", "At the 3 percent inflation a year, because moving the valuation date restates the same value in later money.", "At the applied real rate of 6.796117 percent a year, because AKATA is on the real basis and that is the rate its flows are discounted at.", "By the 2029 flow each year, because each step forward removes one more prior year of -121123680.00 from the value."]'::jsonb, 2, 'The published nominal case grows from 21590909.09 to 23750000.00, one year at 10.000000 percent, because its basis is nominal.'),
  ('cashflow', 'intermediate', 'final', null, 11, 'Valued from 2031 with prior years sunk, AKATA reports sunk_net_cash_flow -89377672.80. Its real cumulative through 2030 is -90302313.79. Which figure is the sunk column, and why?', '["The real cumulative, and the printed -89377672.80 is it compounded forward one year at 6.796117 percent to the 2031 valuation date.", "The nominal cumulative through 2030, -89377672.80, because the sunk column is money of the day like every ledger row.", "The nominal cumulative, because the sunk years are discounted at the nominal rate and only the kept years at the real rate.", "Neither: the sunk column is the two years'' capex of 255000000.00 net of the depreciation claimed, which happens to sit between the two."]'::jsonb, 1, 'The sunk flag removes rows from the value metrics and reports what left; it does not deflate them, and the real basis only ever restates the net total.'),
  ('cashflow', 'intermediate', 'final', null, 12, 'valuation_year_sunk reports take 58.3333 percent where the same rows valued without the sunk flag report 80.7692. No rate changed. Why did the share move?', '["Take is a share of a residual, and the 2030 row left both sides of it: its capex of 50000000.00 left the pre-take value and its royalty of 20000000.00 and tax of 32500000.00 left the government''s part.", "The sunk year''s royalty of 20000000.00 is still counted for the government while its revenue of 100000000.00 is not, so the ratio was computed on mismatched years.", "Take on a sunk run is read on the discounted flows, and the discounted take of a single positive row is lower than the undiscounted take of two rows.", "The engine reads take as the tax rate of 50 percent plus the royalty of 20 percent less the sunk share, which lands on 58.3333."]'::jsonb, 0, 'A take across a sunk boundary is not comparable, in the same way that a take at 75 percent working interest, 74.6292 on AKATA, is not comparable with 66.1723 at 100.'),
  ('cashflow', 'intermediate', 'final', null, 13, 'AKATA valued in 2032 with nothing sunk reads NPV 88351307.89, IRR 29.2361 percent and payback 3.46 years. Why do the IRR and the payback ignore the valuation date?', '["The IRR is a property of the row vector and payback is measured from the first row; only NPV is a value at a date.", "Because the valuation year only takes effect together with treat_prior_as_sunk, and without the flag every metric reads as at 2029.", "Because both are read on the real flows, and the valuation date moves only the nominal column that NPV is built from.", "Because the engine caches the IRR and payback from the base run and recomputes only NPV when the valuation year changes."]'::jsonb, 0, 'With the flag set the IRR becomes null and payback reads Year 0, because rows leave the vector; without it nothing leaves and only the date moves.'),
  ('cashflow', 'intermediate', 'final', null, 14, 'AKATA''s last three discounted rows, 30649858.46, 23167486.48 and 17161022.43, supply most of its 72534830.66. What does that predict for the discount rate sweep?', '["A shallow fall, because the tail rows are already small and a higher rate has little left to remove from small rows.", "A steep fall, because the tail rows are the ones a higher rate reduces most: 48059114.69 at 15 percent nominal and 11736532.11 at 25.", "A rise, because the 2029 row of -121123680.00 is the largest in the ledger and a higher rate would reduce it too.", "No change until the rate passes the IRR of 29.2361 percent, since the NPV of a conventional vector holds its sign to the root."]'::jsonb, 1, 'From 10 to 15 percent nominal the NPV falls from 72534830.66 to 48059114.69, and the profile from 5 to 10 percent falls from 83023565.60 to 55805775.02, both steep because the tail carries the value.'),
  ('cashflow', 'intermediate', 'final', null, 15, 'On multiyear_pia_real the profile point labelled 6.8 reads 203209583.79, the headline 203250580.21, and the engine''s own npv() at 6.796117 percent returns 203250580.21. Which figure was evaluated at the wrong rate?', '["The headline: it was evaluated on the nominal flows at 10.000000 percent while the profile is on the real flows, and the two differ by the deflator.", "Neither: the two differ by floating point accumulation across six rows, and -40996.42 is within the tolerance the finder accepts.", "The profile point: it was evaluated at 6.8 percent, the applied rate rounded to two decimals, and the gap of -40996.42 is the harder discount.", "The npv() figure: a recomputation on the discounted column double-discounts it, which is why it agrees with the headline and not the chart."]'::jsonb, 2, 'The header claims the applied point passes through the headline; on every real basis case it misses, by -21759.68 on AKATA and -453.74 on allowance_cap_midyear.'),
  ('cashflow', 'intermediate', 'final', null, 16, 'jv_analytic_decision_kpis and multiyear_pia_nominal report a profile gap of 0.00 at the applied point. Why do they escape the defect that costs AKATA -21759.68?', '["Their flows are smaller, and the gap scales with the size of the field until it vanishes below the cent.", "Their applied points are computed by the oracle rather than by the engine, and the oracle carries the rate to six decimals.", "Their profiles are sampled at 10 percent, which is a sampled point, while AKATA''s 6.796117 lies between samples and is interpolated.", "Their basis is nominal, so the applied rate is the nominal 10.000000 percent, already a two-decimal number, and rounding it changes nothing."]'::jsonb, 3, 'The rounding only bites when the Fisher rate is not a round number; multiyear_pia_nominal reads 203250580.21 at both the point and the headline.'),
  ('cashflow', 'intermediate', 'final', null, 17, 'AKATA''s payback reads 3.46 years. In which calendar year does the crossing sit, and from where is the duration measured?', '["During 2033, measured from first production in 2030, because the sanction year carries no revenue and is not counted.", "During 2032, measured from the valuation year, so on a run valued from 2030 the same crossing would be reported a year shorter.", "During 2033, measured from the end of the capex years, because payback counts only the years after the last spend of 45000000.00.", "During 2032, measured from the start of the first row, 2029: the nominal running total is -24909427.73 at the end of 2031 and 29050104.71 at the end of 2032."]'::jsonb, 3, 'The crossing is a duration and not a date; on a later-valued run the reported 3.46 years still lands in 2032 because it is measured from the first row.'),
  ('cashflow', 'intermediate', 'final', null, 18, 'AKATA''s 2033, 2034 and 2035 rows, 44874457.77, 37311468.65 and 30401798.05, are deleted. What happens to its payback_years of 3.461632?', '["Nothing; payback sees nothing after the crossing during 2032, and a field with those years removed pays back at exactly the same time.", "It lengthens, because the total net cash flow falls from 141637829.18 and the crossing is a fraction of the total recovered.", "It becomes Beyond project life, because the ledger now ends before the discounted crossing at 3.961607 years.", "It becomes null, because payback needs at least one row after the crossing to interpolate against."]'::jsonb, 0, 'The blindness is shared by discounted payback, which reads 3.961607 years and also crosses during 2032; both refuse to see the tail.'),
  ('cashflow', 'intermediate', 'final', null, 19, 'In the discount rate sweep AKATA''s PV of capex runs from 255000000.00 at 0 percent to 246000000.00 at 25, while DPI falls from 0.555442 to 0.047709. Why does the ratio fall so much faster than its denominator?', '["The denominator is held at the base case 250909090.91 for the ratio while only the numerator is reswept, so the printed PV of capex is a report of the sweep and not the figure the ratio used.", "The numerator is the NPV, which loses its tail rows to the rate, 141637829.18 to 11736532.11, while the capex sits in the first two years where the factor is close to one.", "The DPI is the NPV over the undiscounted capex of 255000000.00 at every point, so the denominator does not move at all in the ratio.", "The discounted take rises from 66.1723 to 94.1819 percent across the sweep, and the DPI is the contractor''s remainder of that share."]'::jsonb, 1, 'At 10 percent nominal the pair is 72534830.66 over 250909090.91, 0.289088, and only the 2030 spend of 45000000.00 is discounted at all.'),
  ('cashflow', 'intermediate', 'final', null, 20, 'single_year_positive and valuation_year_sunk both report DPI null. What do the two cases share?', '["A negative NPV, and the engine suppresses the ratio when the numerator is below zero rather than printing a negative index that a reader might rank on.", "A single row, and a ratio needs at least two rows so that one can be discounted against the other.", "A PV of capex of 0.00: one has no capex, and the other''s only capex year was declared sunk, so there is nothing to divide by.", "A null IRR, and the DPI is derived from the IRR so that one null propagates to the other."]'::jsonb, 2, 'zero_rates_capex_only shows the negative case is printed, -1.381818; single_year_positive reports NPV 35000000.00 and valuation_year_sunk 37500000.00, both positive.'),
  ('cashflow', 'intermediate', 'final', null, 21, 'single_year_positive reports take 61.1111 percent and discounted take 61.1111. AKATA reports 66.1723 and 76.1610. Why do the two takes agree on one case and part on the other?', '["single_year_positive has no capex, and the discounted take only differs from the undiscounted where there is capex to discount, because the capex is the only outflow the government does not share and so the only row that can move the ratio between the two readings.", "single_year_positive is on the nominal basis, where discounting is at 10.000000 percent, and the two takes coincide whenever the applied rate is the nominal one, because the deflator and the discount are then the same factor and cancel between the numerator and the denominator of the share.", "The difference between the two takes is timing, and a one-row field has none: on AKATA the government''s share arrives from 2029 while the contractor''s is recovered in the tail years that discounting reduces most.", "AKATA''s royalty of 15 percent is discounted and its tax of 40 percent is not, and the split is what opens the gap: royalty is charged on revenue as it arrives, so it carries an exponent, while tax is settled on the year''s income and is carried at face value in both readings."]'::jsonb, 2, 'Every published case with a tail shows the same direction, multiyear_jv_real 69.2573 against 75.4578 and multiyear_pia_real 71.1024 against 77.4499.'),
  ('cashflow', 'intermediate', 'final', null, 22, 'At 60 percent working interest AKATA reports NPV 43520898.40, IRR 29.2361 percent and take 79.7034 percent. Which of the three is a reading of the whole field rather than of your share?', '["The NPV: 43520898.40 is the field''s value at the discount rate, and the working interest is applied afterwards to report your part of it, because the engine discounts the whole field''s flows first and scales the sum, so the printed NPV is field-level.", "The take: it is the share of the whole field''s pre-take value that does not reach your ledger, partners included, while the NPV is your share and the IRR is the same at any share.", "The IRR: 29.2361 percent is the return on the whole field''s capex of 255000000.00 and would fall if only your 60 percent were counted.", "No single one: every KPI on a working-interest run is scaled to your share, which is why the take rises from 66.1723 at 100 percent to 79.7034, since a smaller share of the net cash flow leaves a larger share of the field''s value with the government and the partners alike."]'::jsonb, 1, 'At 25 percent the take reads 91.5431 and the NPV 18133707.67 while the IRR still reads 29.2361, because scaling a vector leaves its zero fixed.'),
  ('cashflow', 'intermediate', 'final', null, 23, 'AKATA''s rate sweep reads NPV 11736532.11 at 25 percent nominal, and its IRR is 29.2361 percent. What is the relation between the two numbers?', '["No relation; the IRR is solved on the nominal flows and the sweep is on the real basis, so its zero lies at a different rate from the sweep''s.", "The IRR is 25 percent plus the applied real rate of 21.359223 less the inflation, which is how the sweep''s last row relates to the root.", "The sweep would reach zero at 6.796117 percent real, and the IRR is that rate restated as nominal.", "The IRR is the nominal rate at which the sweep''s NPV would reach zero, so a positive NPV at 25 percent is required by an IRR above 25."]'::jsonb, 3, 'At 20 percent nominal the sweep reads 28144510.75 and at 25 it reads 11736532.11; the crossing lies where the IRR says, beyond the table.'),
  ('cashflow', 'intermediate', 'final', null, 24, 'two_roots_10_and_20, [-100, 230, -132], has roots at 10 and 20 percent and reports 10.0000. Why 10 rather than 20?', '["Newton starts at 10 percent and is already on a root, so it reports that one; the choice is an accident of the start, not a rule.", "The engine reports the root nearest zero on the positive side, the hurdle-rate region, which is the oracle''s rule and the one the method statement adopts.", "The engine reports the lower root because a lower IRR is the conservative reading of a two-root vector.", "Bisection brackets the interval from 0 to 20 percent and halves it toward the lower crossing first."]'::jsonb, 0, 'On two_roots_2_and_6 the same start reads -0.264463 at 10 percent and climbs to the root at 6, where the oracle''s rule gives 2.0000.'),
  ('cashflow', 'intermediate', 'final', null, 25, 'all_positive [5, 5, 5], all_negative [-5, -5] and no_real_root [-1, 3, -3] each report IRR null. What in the return tells the three reasons apart?', '["The sign of the null: the engine returns a positive null for a curve that stays positive and a negative null for one that stays negative.", "Nothing in the IRR field; only the NPV beside the null, 15.00, -10.00 and -1.00 at 0 percent, says which shape you have.", "The residual printed with the null, which reads 0.000000 for a curve that touches zero and is absent for one that never approaches it.", "The method statement, which names the branch that failed: no sign change for the first two and unconverged Newton for the third."]'::jsonb, 1, 'AKATA valued from 2030 with 2029 sunk reads null beside 206819768.67, and AKATA at 30 USD/bbl null beside -169873348.04; the null is the same and the NPV is not.'),
  ('cashflow', 'intermediate', 'final', null, 26, 'two_roots_minus73_and_173 reports 173.6932 percent with a residual of 0.000000, and its sampled curve also changes sign between -75 and -50 percent. What does the residual prove?', '["That the root is unique, because a residual of exactly zero is only reached when the curve crosses once.", "That the crossing between -75 and -50 is spurious, since a converged root supersedes any sign change at a negative rate.", "That 173.6932 is a root, and nothing about the other crossing; a residual is a statement about one point of the curve.", "That the finder used bisection, because Newton reports its residual as -0.000000 and bisection as 0.000000."]'::jsonb, 2, 'The curve reads -6500000.000000 at -75 and 26500000.000000 at -50 percent, a bracket the finder never visited on its way from 10 percent to 173.6932.'),
  ('cashflow', 'intermediate', 'final', null, 27, 'two_roots_2_and_6 reports 6.0000 percent. Its NPV at a hurdle of 5 percent is 0.027211. Does the approval hold, and on what ground?', '["It holds because the NPV at 5 percent is positive, which is the sign the decision needs; the reported 6.0000 against 5 was not the ground.", "It holds because 6.0000 exceeds 5, and an IRR above the hurdle is the definition of approval on any vector.", "It fails because the oracle''s root is 2.0000, below the hurdle, and the lower root governs on a terminal-negative vector since it is the first rate at which the curve is zeroed.", "It fails because the NPV of 0.027211 is within the finder''s tolerance and cannot be told from zero."]'::jsonb, 0, 'On three_roots_0_7_33 the same IRR comparison, 7.3509 against 5, approves a vector whose NPV at 5 percent is -0.028075.'),
  ('cashflow', 'intermediate', 'final', null, 28, 'AKATA at 40 USD/bbl reports IRR -21.3703 percent and NPV -115833227.55; at 30 USD/bbl it reports IRR null and NPV -169873348.04. Why does one uneconomic run get a rate and the other none?', '["At 40 the field still pays tax in three years, 13834880.00, 7217644.80 and 2950616.45, and a root exists while any tax is paid, because a taxable income is a positive income and a positive income somewhere in the vector is what the finder brackets.", "At 30 the root is below -100 percent and the finder refuses to report a rate that would mean losing more than everything, because the discount factor at such a rate is undefined and the method statement returns null rather than a rate it cannot evaluate.", "At 30 the payback reads Beyond project life, and the finder returns null whenever the payback is null.", "At 40 a sign change still brackets a root below zero, the rate at which a shrinking discount makes the receipts worth the outlay; at 30 no sampled rate produced a positive NPV."]'::jsonb, 3, 'loss_making, [-1000, 500, 400], reports -6.9926 percent for the same reason as the 40 USD/bbl run: a negative IRR is a legitimate root.'),
  ('cashflow', 'intermediate', 'final', null, 29, 'AKATA with a 200000000 abandonment reports headline NPV -40359955.35 and IRR null, while its NPV of the nominal flows is -58362170.82 at 0 percent and -81068008.48 at 100. Why is the headline less negative than the 0 percent figure?', '["The headline is on the real basis, where the abandonment is deflated by six years of 3 percent, and the 0 percent figure is nominal, so the deflator shrinks the terminal -169598201.95 in the headline and leaves it at face value in the nominal figure, which is the whole of the difference.", "The headline excludes the abandonment as a sunk liability, and the 0 percent figure carries it at face value, because a lump sum in the last year is treated by the value metrics as a provision already made and reported separately, the way a sunk year is reported as sunk_net_cash_flow.", "The 0 percent figure is the profile''s sampled point and the headline the exact one, and the gap is the rounding defect on a negative field, where rounding the applied rate to two decimals discounts a negative tail less harshly and the sign of the gap reverses from the -21759.68 seen on the base case.", "Discounting reduces the terminal -169598201.95 more than the positive middle rows because it is furthest from 2029, so a moderate rate makes this vector less negative before the high rates make it more so."]'::jsonb, 3, 'A curve that is negative at 0, less negative in the middle and negative again at 100 percent never crosses, so there is no bracket and the IRR is null.'),
  ('cashflow', 'intermediate', 'final', null, 30, 'AKATA''s total tax is 279459095.32 at 120 USD/bbl and 7156724.80 at 30. What does the movement of the tax column say about a sweep point?', '["The tax column is the base run''s 148425219.46 scaled by the ratio of the new price to 82, which is what a rescaling of revenue implies when every deduction is a fixed share of revenue.", "Each point is a full rerun of the ledger, cascade included, so the tax column is recomputed at each price rather than carried from the base run.", "The tax column moves because the tax rate is swept together with the price, from 40 percent at 82 to a lower rate at 30.", "The tax column moves because the economic limit trims years at low prices, and a trimmed year carries no tax."]'::jsonb, 1, 'At 50 USD/bbl the last two years pay 0.00 because depreciation of 25500000.00 and escalated opex outrun the revenue, a fact only a rerun of the cascade can produce.'),
  ('cashflow', 'intermediate', 'final', null, 31, 'Across AKATA''s price sweep the take rises from 57.9418 percent at 120 USD/bbl to 87.4083 at 60 while total tax falls from 279459095.32 to 75781881.55. How can the share rise while the sum falls?', '["The take is read on the discounted flows and the tax on the nominal ones, and discounting weighs the early royalty more heavily at low prices, because the contractor''s recovery is pushed later as the price falls and the tail years are the ones the discount reduces most.", "The tax rate rises as the price falls under the JV terms, so a smaller sum is a larger share of a smaller income, because the depreciation of 25500000.00 a year is a fixed deduction and a fixed deduction against a smaller revenue leaves the 40 percent rate biting on a larger fraction of what remains.", "Take is a share of the pre-take value, and that residual shrinks faster than the government''s sum as the price falls, because royalty at 15 percent is charged on revenue whatever the residual.", "The take at low prices includes the loss carried forward, which counts as a government receipt until it is used."]'::jsonb, 2, 'At 50 USD/bbl the residual is so small that the take passes 100 percent, 135.2824, and at 40 it is not positive and the take is null.'),
  ('cashflow', 'intermediate', 'final', null, 32, 'A reader asks for AKATA swept on the real discount rate directly, from 0 to 20 percent real. What does the engine offer?', '["No such sweep: the real rate is derived from the nominal rate and the 3 percent inflation, so the nominal rate is swept and the applied real rate follows, -2.912621 at 0 to 21.359223 at 25.", "A real sweep on request, which reads the same NPVs as the nominal one because the two bases agree end-year, so a real rate of 0 percent reads the real total 117362408.71 where the nominal sweep''s 0 percent row reads the nominal total 141637829.18, and the two rows are the same field.", "A nominal sweep with inflation set to zero, which makes the real and nominal rates coincide at every point, so that the applied real rate reads 10.000000 percent at 10 nominal and the NPV of 72534830.66 is unchanged because inflation never moved it in the first place.", "The inflation sweep, which moves the real rate from 10.000000 to 1.851852 percent while holding the nominal rate at 10, so that each row of it is a reading of AKATA at a different real rate and the real total, 141637829.18 down to 83912631.29, is the NPV at that rate."]'::jsonb, 0, 'The inflation sweep does move the applied real rate, but NPV stays 72534830.66 at every point, so it is not a sensitivity to the rate at all.'),
  ('cashflow', 'intermediate', 'final', null, 33, 'AKATA is given a price deck and its breakeven reads null. Is the field uneconomic?', '["No; with a deck there is no single flat price to move, so the search cannot run, and only the NPV under the deck says whether the field pays.", "Yes; null is the value the search returns when no price in its range turns the NPV positive, and a deck that holds the price at 100 in 2030 is a price the search has already tried and found wanting.", "Yes; a deck fixes the price and a field whose price cannot move cannot break even.", "No; the breakeven under a deck is the deck''s own first entry, oil 100 in 2030, and the null is a formatting of that entry, because a deck price is a price the owner has fixed and a fixed price needs no search to find."]'::jsonb, 0, 'deck_present_null has a deck of one entry, oil 100 in 2030, and reports null; never_breaks_even_null reports null because no price in the search turns the NPV positive, a different reason behind the same null.'),
  ('cashflow', 'intermediate', 'final', null, 34, 'Between 10 and 20 percent decline unit technical cost rises from 45.497913 to 57.021318 USD/boe and four years are trimmed. Can the table separate the decline''s effect from the trimming''s?', '["Yes: the trimming removes the capex of the trimmed years, and the difference in total capex is the trimming''s share.", "Yes: unit technical cost is an undiscounted reading and the limit only trims the discounted column, so the rise is decline alone.", "No: the cost is spread over fewer barrels for both reasons at once, and the two rows compare a ten-row field with a six-row one.", "Yes: the take, 75.6417 against 105.7792, isolates the trimming because the take is invariant to decline."]'::jsonb, 2, 'The rows column, 10 against 6, is the first thing to read; the NPV moves from 153012318.45 to -76483227.81 for the same two reasons at once.'),
  ('cashflow', 'intermediate', 'final', null, 35, 'AKATA with capex at 1.5 of base reports NPV -27542077.46 and IRR 5.7351 percent. Is a positive IRR beside a negative NPV a contradiction?', '["Yes: a positive IRR means the project earns a positive return, so the NPV at any rate should be positive too.", "No: the IRR is the rate at which NPV is zero, 5.7351 percent, and the configured nominal 10 sits above it, so the NPV at 10 is negative; the two agree.", "Yes: the IRR is solved on the real flows at 6.796117 percent and the NPV on the nominal ones at 10, and the two runs disagree because the deflator has been applied to one vector and not the other.", "No: the IRR is unaffected by capex scale, so 5.7351 is the base case''s rate restated and the NPV is the only figure that moved, in the same way that the working interest leaves 29.2361 percent fixed at every share."]'::jsonb, 1, 'At 1.2 of base the IRR is 16.7435 percent and the NPV 32917744.31, positive, because the root has moved back above the nominal 10.'),
  ('cashflow', 'intermediate', 'final', null, 36, 'AKATA''s price sweep runs the oil price from 30 to 120 USD/bbl and holds the gas price at 3.2 USD/Mscf at every point. What does that make the sweep?', '["A sweep on total revenue, since the gas is priced off the oil at 800 scf per barrel and follows it.", "A sweep on the oil escalator, since the gas escalator of 2 percent is the one held still.", "A sweep on boe, since 6 Mscf per barrel converts the gas into oil terms and the price is applied to the sum.", "A sweep on oil alone: the flat oil_price_usd_bbl moves, and the gas revenue is the same at every point."]'::jsonb, 3, 'AKATA''s gas is 7744000.00 Mscf against 9680000.00 bbl of oil, and its revenue at 3.2 USD/Mscf does not change across the nine points.'),
  ('cashflow', 'intermediate', 'final', null, 37, 'A reader reports AKATA''s NPV as 70188970.32, and only afterwards discovers that the run was mid-year on the real basis. What does the method call this?', '["A reconciliation problem: the two facts are consistent, and the reader has only to recompute 70188970.32 at the exact applied rate of 6.796117 percent, where the profile point that was read misses the headline by -21759.68.", "Working the steps out of order: every number changes meaning when a convention is found late, and naming the convention first is what stops the numbers betraying you.", "A sunk-year problem: a mid-year run on the real basis sinks the valuation year row by discounting it half a year, so the reader is holding an NPV with the 2029 capex partly written off and needs the sunk figure of 206819768.67 to compare.", "A basis problem: 70188970.32 is the real basis figure and the reader needs the nominal 69159247.46 to proceed."]'::jsonb, 1, 'The convention sentence is written first; 70188970.32 is real basis, mid-year, 10 percent nominal, 3 percent inflation, valued in 2029, and a reader who learns that last has read the number wrong until then.'),
  ('cashflow', 'intermediate', 'final', null, 38, 'The onward lesson says the Expert tier''s fiscal cascade is read with the conventions this tier named. What does that mean for a PIA NPV such as 203250580.21 on multiyear_pia_real?', '["It carries the same label: real basis, end-year, 10 percent nominal at 3 percent inflation, applied 6.796117; its mid-year twin reads 196677221.27 and its profile gap of -40996.42 is the same defect.", "It is convention-free, because the PIA cascade is charged on undiscounted bases and the NPV is a sum of after-tax rows, so the discount rate, the basis and the timing convention enter only the JV ledger, and a PIA NPV is the same number under every reading of time.", "It needs its own conventions, because five taxes on three bases each carry a timing rule that the JV ledger does not, so the royalty, the HCT, the CIT and the levy are each placed in time separately and a PIA NPV is labelled by the timing of each tax rather than by one convention.", "It is read nominal only, because the PIA''s price royalty tiers are in money of the day and cannot be deflated, so the real basis is refused on a PIA run and the profile is evaluated on the nominal flows at the nominal 10.000000 percent with no Fisher conversion and no rounding gap."]'::jsonb, 0, 'Nothing learned in the Professional tier is replaced in the Expert tier; multiyear_pia_nominal reads 203250580.21 too, because the bases agree end-year.'),
  ('cashflow', 'intermediate', 'final', null, 39, 'The tier''s closing exercise asks for the six conventions that label 72534830.66. Which six?', '["Basis, convention, nominal rate, real rate, inflation and the escalators, because each of them enters the discount factor.", "Royalty, tax rate, working interest, oil price, discount rate and inflation, the inputs a sensitivity would sweep.", "Basis, convention, nominal rate, inflation, valuation year and the treatment of prior years.", "Basis, convention, valuation year, abandonment, decline rate and the economic limit, which shape the tail of the vector."]'::jsonb, 2, 'The real rate is derived and not chosen, and the fiscal inputs write the rows; the six conventions are the rules for reading rows that are already written.'),
  ('cashflow', 'intermediate', 'final', null, 40, 'The story so far records that at 20 percent decline the published PIA field loses four years to the economic limit and its take reads 105.7792 percent. Read with the rows column, what does that take say?', '["That the field pays more than it earns, which is an error in the cascade the engine should have reported as null.", "That the PIA royalty tiers rise with decline, since a faster decline raises the price tier the field is charged at, and a higher tier on the surviving rows lifts the government''s share of a residual that has not otherwise changed.", "That the trimmed years'' royalties are still counted while their revenue is not, which inflates the share past 100, because the limit removes revenue rows from the valued ledger while the royalty column keeps its total of 228146979.52.", "That it is a share of a residual on a six-row field, close to zero after trimming, and not comparable with the 75.6417 percent of the ten-row run at 10 percent decline."]'::jsonb, 3, 'At 40 percent decline three rows survive and the take reads 1199.4096 percent, a denominator that has almost vanished, not a rounding fault.'),
  ('cashflow', 'intermediate', 'final', null, 41, 'The onward lesson says the profile gap of -21759.68 travels as the first number to distrust. Distrust it for what?', '["For the headline: the profile is the more precise figure because it is on the chart, and the headline of 72534830.66 should be corrected down by the gap to the charted 72513070.98, which is the figure the engine evaluated last and therefore the one it stands behind.", "For the basis: the gap appears on the real basis only, which shows the real basis is the less reliable of the two.", "For the IRR: a profile that misses at the applied rate misses at every rate, so the 29.2361 percent read from it is suspect, and the oracle''s habit of reporting the root nearest zero on the positive side is the correction the reader should apply to it.", "For reconciliation: the applied-rate marker sits at 6.8 rather than 6.796117 percent, so an analyst who hunts for 21759.68 in a spreadsheet finds nothing, because the error is the engine''s rounding."]'::jsonb, 3, 'The engine''s npv() at the exact rate returns 72534830.66; the profile point is the one at the wrong rate, and the IRR is never read from the profile at all.'),
  ('cashflow', 'intermediate', 'final', null, 42, 'AKATA reads 72534830.66 under nominal end-year and under real end-year, 69159247.46 under nominal mid-year and 70188970.32 under real mid-year. Which of basis and convention moves NPV, and when does the other begin to?', '["The basis always moves it, by the deflation of 141637829.18 to 117362408.71; the convention only moves it on the nominal basis.", "The convention always moves it; the basis moves it only under mid-year, where the half-year factor differs between 10.000000 and 6.796117 percent.", "Both always move it, and the two end-year figures agree by the coincidence of 3 percent inflation against 2 percent escalators, which happen to offset each other over AKATA''s seven years.", "Neither moves it on its own; only the two changed together, from nominal end-year to real mid-year, produce a different figure, because each alone is a relabelling of the same discounted column."]'::jsonb, 1, 'Under end-year the deflated flows at the deflated rate multiply back to the nominal factor exactly; under mid-year the half-year shift is a square root of a different number on each basis.');
